quests[75831] = { id = 75831, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach oben tauschen", description = "Seid gegrüßt, <mein Freund/meine Freundin>\n\nWie ich höre, habt Ihr etwas gefunden, an dem ich Interesse haben könnte. \n\nEin sehr geruchsintensives Stück, ich würde es gern sehen. \n\nIhr wisst schon, einfach um zu sehen, ob es meine Zeit wert ist. \n\nEuer besonders netter Freund, \n\nPonzo", sourceObjective = "Bringt den stinkenden Happen zu Ponzo in Loamm.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[75833] = { id = 75833, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldet Euch im Handelsposten", description = "<Das Funkeln eines entfernten Objekts zieht Eure Aufmerksamkeit auf sich. Ihr erinnert Euch plötzlich, dass Ihr Devisen für den T&W-Handelsposten sammeln müsst.>", sourceObjective = "Kehrt zum Handelsposten zurück und nehmt Eure Händlerdevisen aus der Truhe des Sammlers.", completion = "Ich hoffe, Euch gefällt die monatliche Sammlung neuer und exotischer Waren, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[75834] = { id = 75834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stöberin Mardei", sourceObjective = "Besiegt Stöberin Mardei in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[75835] = { id = 75835, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trainiert Ihr überhaupt?", sourceObjective = "Besiegt Ausbilder Orlogg in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[75859] = { id = 75859, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterstützt das Abkommen: Schnüffelsuchen", description = "Unsere Verbündeten brauchen einmal mehr Eure Unterstützung bei ihren Vorhaben auf den Inseln. In Valdrakken gehen Worte des Trostes um, die davon sprechen, wie Ihr geholfen habt, unsere Zukunft zu formen.\n\nDoch zurück zur Sache.\n\nUnsere Niffenverbündeten in der Zaralekhöhle sind immer auf der Suche nach neuen und aufregenden... oder stinkenden Dingen. Geht mit ihnen in den vielen verlorenen und vergessenen Höhlen ihres Reiches graben und seht, was Ihr finden könnt.\n\nWir erwarten Eure Rückkehr, {name}.", sourceObjective = "Reist zur Zaralekhöhle und begleitet Myrrit in Loamm auf einer unterirdischen Grabung. Führt Eure Bemühungen fort, dem Valdrakkenabkommen und seinen Verbündeten auf den ganzen Dracheninseln zu helfen.", completion = "Das sind wundervolle Neuigkeiten! Das Abkommen wird froh sein, von Euren Taten zu hören.\n\nNehmt bitte dies als Zeichen unserer Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[75860] = { id = 75860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterstützt das Abkommen: Forscher unter Feuer", description = "Unsere Verbündeten brauchen einmal mehr Eure Unterstützung bei ihren Vorhaben auf den Inseln. In Valdrakken gehen Worte des Trostes um, die davon sprechen, wie Ihr geholfen habt, unsere Zukunft zu formen.\n\nDoch zurück zur Sache.\n\nForscher der Drachenschuppenexpedition erkunden die Tiefen der Zaralekhöhle. Sie suchen tapfere Abenteurer, die sie vor den vielen Gefahren dieses Gebietes schützen.\n\nWir erwarten Eure Rückkehr, {name}.", sourceObjective = "Reist zur Zaralekhöhle und schützt die Forscher unter Feuer. Führt Eure Bemühungen fort, dem Valdrakkenabkommen und seinen Verbündeten auf den ganzen Dracheninseln zu helfen.", completion = "Das sind wundervolle Neuigkeiten! Das Abkommen wird froh sein, von Euren Taten zu hören.\n\nNehmt bitte dies als Zeichen unserer Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[75861] = { id = 75861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterstützt das Abkommen: Durchdringungslager", description = "Asche kommt aus dem Süden.\n\nZwischen Fyrakk und den Djaradin der Zaqali wurde ein dunkler Pakt geschlossen, {name}. Ihre Streitkräfte bauen... etwas.\n\nWir wissen nicht, was sie vorhaben, aber sie haben bislang nicht gezögert, alles und jeden in ihrem Weg zu verdrängen.\n\nBitte, {name}, wir brauchen Champions wie Euch, um diese Bösewichte zu untergraben und ihrer Ressourcen zu berauben.\n\nWir erwarten Eure Rückkehr, {name}.", sourceObjective = "Reist zu einem Durchdringungslager und plündert eine gesicherte Lieferung. Führt Eure Bemühungen fort, dem Valdrakkenabkommen und seinen Verbündeten auf den ganzen Dracheninseln zu helfen.", completion = "Wir können so viel von Euren Bemühungen lernen. Was haben sie gemacht? Nun, das ist ein Geheimnis, das es später zu lösen gilt.\n\nNehmt dies bitte als Zeichen unserer Dankbarkeit an.", sourceObjectiveStatus = "unverified-source-field" }
quests[75865] = { id = 75865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relikträuber", description = "Eine Gruppe, gemeiner, schuppiger Oberländer hat bei den alten Titanenruinen südlich von Loamm ihr Lager aufgeschlagen und angefangen, den Ort auseinanderzunehmen.\n\nSehr unhöflich, obwohl sie alle möglichen uralten Titanenteile gefunden haben dürften. Und dieses Zeug ist fast immer irgendwie magisch.\n\nSchnappt Euch ein paar und findet heraus, was Staubhändler Topuiz in Loamm damit anfangen kann!", sourceObjective = "Sammelt 8 Reliktsplitter.", progress = "Ich kann kaum erwarten zu sehen, was Ihr aufdeckt!", completion = "Wunderbar! Die riechen uralt... und gerade richtig prickelnd!", sourceObjectiveStatus = "unverified-source-field" }
quests[75867] = { id = 75867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Verbindung in die Vergangenheit", description = "Gut, Kalibrierung abgeschlossen! Meine auch, also werde ich sehen, was Ihr seht.\n\nGehen wir rüber zum Teleskop und dann sehen wir mal, was wir sehen.", sourceObjective = "Beobachtet die Ereignisse der Vergangenheit.", progress = "Ich frage mich, was wir finden werden?", completion = "Für sie ist es schade, aber für uns vielleicht eine Gelegenheit. Hmm...", sourceObjectiveStatus = "unverified-source-field" }
quests[75868] = { id = 75868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Fenster in die Zukunft", description = "Diese Linsen sind eine wunderbare Verbindung von Technologie und arkaner Handwerkskunst. Ich bin sicher, dass wir viel lernen und meine eigene Erfindung vielleicht sogar verbessern können.\n\nAber zuerst müssen wir sie finden. Ihr seid <Drachenreiter/Drachenreiterin>, oder? Könnt Ihr dort hochfliegen und die Linse zurückholen?\n\nEs ist möglich, dass die Schreckenswinde sie immer noch in einem ihrer Nester haben.", sourceObjective = "Durchsucht Schreckenswindnester, um die Linse zurückzuholen.", progress = "Habt Ihr die Linse gefunden, {name}?", completion = "Geschafft!\n\nIch wusste, Ihr seid die richtige Person für diese Aufgabe!", sourceObjectiveStatus = "unverified-source-field" }
quests[75874] = { id = 75874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit für den Abflug", description = "Zandalar ist Heimat vieler Pterrordaxe. Ein Exemplar wird Euch in die Lüfte begleiten.\n\nStattet Meister der Tiere Kalatak bei Dazar'alor in Zuldazar einen Besuch ab.", sourceObjective = "Findet Meister der Tiere Kalatak.", completion = "Ich bin froh, dass Ihr gekommen seid. Dieser Pterrordax ist unruhig und sehnt sich danach, die Welt jenseits von Zandalars Küsten zu sehen. Ich kann ein solches Tier nicht ausbilden.\n\nNehmt Ihr es nur. Möge es Euch auf Euren Reisen Glück bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[75877] = { id = 75877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit für den Abflug", description = "Kul Tiras ist Heimat vieler Greife. Ein Exemplar wird Euch in die Lüfte begleiten.\n\nStattet Leni Stevers am Handelswindmarkt in Boralus einen Besuch ab.", sourceObjective = "Findet Leni Stevers.", completion = "Ich bin froh, dass Ihr gekommen seid. Dieser junge Greif wurde zurückgelassen, als die übrigen Exemplare in die Ausbildung geschickt wurden. Ich hätte nie gedacht, dass er eines Tages so weit sein würde, aber nun ist er tatsächlich bereit, zu fliegen.\n\nWürdet Ihr ihn für mich mitnehmen und ihm die ganze Welt zeigen? Möge er Euch auf Euren Reisen Glück bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[75885] = { id = 75885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Handumdrehen reich", description = "<Oberländer/Oberländerin>! Gestattet mir eine Frage. \n\nWürdet Ihr gerne auch einen so teuren Hut wie meinen tragen? Die Freuden des Lebens genießen?\n\nWenn Eure Antwort \"Ja\" lautet, macht Euch bereit, reicher zu werden, als Ihr es Euch je erträumen könntet! Im Ponzo-Stil!\n\nGemeinsam können wir beide richtig reich werden! Natürlich bin ich schon reich, aber Ihr könnt es auch sein!\n\nNehmt einfach diese Gegenstände und zeigt sie in der Stadt herum. Ihr erhaltet von mir dann für jede Bestellung, die Ihr in trockene Tücher bringt, einen Anteil.", sourceObjective = "Bringt die Bürger von Loamm dazu, Ponzos Creme und Teilnutzungsgutscheine für Glimmerogg zu kaufen.", progress = "Habt Ihr irgendwelche Befehle erhalten?", completion = "Ihr habt das so toll gemacht, dass ich sogar einen Bonus für Euch habe.\n\nIhr könnt jetzt noch mehr Dinge bei mir kaufen und selbst so viel verkaufen, wie Ihr wollt. Und jeder Eurer Verkäufe macht uns beide noch reicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[75887] = { id = 75887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fyrakks Truppen", description = "Hört Champion, Fyrakk und seine verbündeten Primalisten sind einen dunklen Handel mit den Djaradin eingegangen. Wir haben erfahren, dass ihre Streitkräfte die Dracheninseln überfallen. Sie suchen nach Ressourcen für irgendein unheilvolles Projekt.\n\nBitte, Champion, findet eines dieser Durchdringungslager und helft unseren Verbündeten, die Ihr dort findet.", sourceObjective = "Reist zu einem Durchdringungslager.", completion = "Gut! Wir brauchen jeden Sterblichen und jeden Drachen, den wir finden können, um dieses Ungeziefer zurückzuschlagen. Ich hoffe, Ihr seid bereit für einen Kampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[75888] = { id = 75888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchdringungslager", description = "Fyrakk hat eine Abmachung mit den drachenjagenden Djaradin getroffen!\n\nIhre Schmiedin, Igira, hat ihre besten Handwerker dem Kommando von Fyrakks Primalisten unterstellt. Sie sammeln Materialien für den Bau von... irgendetwas.\n\nFindet einen Zugang zu ihren Durchdringungstiegeln und -formen. Behaltet, was Ihr findet, aber wir müssen mehr darüber erfahren, was sie tun. Sie scheinen spezielle Schutze zu brauchen, um auf die Tiegel und Formen zugreifen zu können. Fangt da an.", sourceObjective = "Erbeutet einen Durchdringungstiegel und eine Durchdringungsform.", completion = "Schattenflamme! Sie durchdringen alles Material und jede Komponente mit Schattenflamme!\n\nWas stellen sie nur her? Es muss etwas sehr viel Gefährlicheres sein als simple Armeeausstattung.\n\nGut gemacht, Held. Wir müssen einen besseren Nutzen für diese Materialien finden als diese Bestien.", sourceObjectiveStatus = "unverified-source-field" }
quests[75890] = { id = 75890, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf der Fanfare", description = "Schön, Euch zu sehen, {name}. Ich habe eine Nachricht von einer gewissen Arko'narin Sternschatten. Da steht...\n\n\"Als Beschützerin der Kaldorei muss ich Euch bitten, mich in der Nähe der Botschaft in Sturmwind zu treffen. Tyrande hat die Wächterinnen ausgesandt, und sogar Maiev Schattensang selbst hat um Eure Unterstützung in dieser Angelegenheit gebeten.\"\n\nArko'narin Sternschatten", sourceObjective = "Sprecht mit Arko'narin Sternschatten in der Nähe der Botschaft von Sturmwind.\n\nBereitgestellter Gegenstand:", completion = "Es ist mir eine Ehre, Euch kennenzulernen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[75891] = { id = 75891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uralte Flüche", description = "Danke, dass Ihr meinem Ruf so schnell gefolgt seid, {name}.\n\nIm Teufelswald lebt die dämonische Verderbnis in letzter Zeit wieder auf. Tyrande hat mehrere Schildwachen und eine ihrer eigenen Priesterinnen ausgesandt, um die Angelegenheit genauer zu untersuchen. Niemand ist zurückgekehrt.\n\nTyrande hat die Wächter gebeten, sich der Sache anzunehmen, und Maiev bittet persönlich um Eure Unterstützung.\n\nWir müssen uns rasch in den Teufelswald begeben und prüfen, was Maiev entdeckt hat.", sourceObjective = "Trefft Maiev Schattensang im Teufelswald.", progress = "Möge Elune uns an diesem trostlosen Ort alle zum Sieg führen.", completion = "Ich werde Euch erklären, was wir tun müssen, {name}.\n\nAber lasst mich erst meine Freundin zur Ruhe betten.", sourceObjectiveStatus = "unverified-source-field" }
quests[75918] = { id = 75918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuersaison", description = "Ihr habt zweifelsohne die Vernichtung gesehen, die Fyrakk auf seinem Weg zurücklässt.\n\nWährend andere ihn direkt bekämpfen, dienen meine Truppen und ich als Augen und Ohren des grünen Drachenschwarms. Auch wenn Fyrakk völlig zufällig zu handeln scheint, gibt es doch gewisse Gemeinsamkeiten bei seinen Strategien.\n\nWir haben erfahren, dass er bald in Lunedane ein geheimes Treffen mit Vyranoth abhalten wird. Dies ist eine Abweichung von seinen letzten Taktiken, und wir müssen den Grund erfahren.\n\nEs wird gefährlich, also würden wir Eure Hilfe zu schätzen wissen. Sucht mich in Lunedane auf.", sourceObjective = "Trefft Shandris bei Lunedane auf den Ebenen von Ohn'ahra.", completion = "Bleibt in den Schatten, {name}.\n\nLunedane ist bereits voll von Fyrakks Truppen.", sourceObjectiveStatus = "unverified-source-field" }
quests[75919] = { id = 75919, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schutze löschen", description = "Fyrakk und Vyranoth sind bereits hier. Ich habe sie in der Nähe eines Rundblicks am nordöstlichen Ende von Lunedane entdeckt. Würdet Ihr zu nah an ihnen landen, würden sie uns bemerken, daher müssen wir mit unserer Mission hier beginnen.\n\nJedoch ist die Brücke, die zum Rundblick führt, durch Feuermagie geschützt. Wir werden nicht in der Lage sein, sie zu durchbrechen.\n\nFyrakks Primalisten scheinen das Feuer mit Schutzen aufrechtzuerhalten, die in der Umgebung verteilt sind.\n\nWenn wir die Schutze zerstören, sollte das Feuer erlöschen.", sourceObjective = "Zerstört 4 Schutzfeuersteine.", progress = "Wir müssen diese Barriere überwinden, damit wir uns den Inkarnationen nähern können. Von hier hören wir sie nicht.", completion = "Nachdem wir diese Steine zerstört haben, scheint die Feuermagie auf der Brücke verschwunden zu sein.\n\nIch kann aber nicht sicher sagen, wie lange das so bleibt. Wir sollten schnell hinüber.", sourceObjectiveStatus = "unverified-source-field" }
quests[75920] = { id = 75920, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Augen des Feuers", description = "Hier sind viel mehr Primalisten, als ich erwartet habe. Fyrakk reist normalerweise nicht mit Wachen, also bezweifle ich, dass die Primalisten hier sind, um ihn zu begleiten.\n\nSie scheinen hier einen Brückenkopf errichten zu wollen. Aber warum?\n\nVielleicht beantwortet das, was auch immer die Inkarnationen besprechen, diese Frage.\n\nBis dahin sollten wir die Primalisten ausdünnen, die in dieser Gegend Wache schieben. Wir können nicht riskieren, sie alle in unserem Rücken zu haben, wenn wir die Brücke überqueren.", sourceObjective = "Tötet 8 brennende Flammensprecher oder lodernde Aufseher.", progress = "Wir werden schnell vorgehen müssen. Wir dürfen nicht riskieren, die Aufmerksamkeit der Inkarnationen zu wecken.", completion = "<Shandris wirft einen Blick zurück auf die Leichen der Druiden. Sie scheint bestürzt, aber da ist auch Schmerz in ihren Augen.>\n\nDruiden der Flamme?\n\nFyrakk hat sie in seine Dienste aufgenommen?\n\nWarum sollten Nachtelfen an so etwas teilhaben...?", sourceObjectiveStatus = "unverified-source-field" }
quests[75921] = { id = 75921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch die Flammen", description = "Druiden der Flamme...\n\n<Shandris sieht aufgebracht aus, die Augen fest geschlossen, als sie ihre Wut zurückhält.>\n\nDass sie überhaupt noch existieren. Dass Mitglieder unseres Volkes sich Fyrakk und seiner...\n\n<Sie hält inne, atmet schwer aus und spricht weiter.>\n\nWir haben einen Auftrag zu erfüllen.\n\nWir müssen die Brücke überqueren und uns den Inkarnationen weit genug nähern, um ihr Gespräch zu belauschen. Ich werde uns verhüllen, damit wir uns durch die Elementare bewegen können, die immer noch den weiteren Pfad bewachen.", sourceObjective = "Sammelt 4 schwelende Blüten, während Ihr die Brücke zu Fyrakk und Vyranoth überquert.", progress = "Wir müssen uns den Inkarnationen so weit nähern wie möglich.\n\nWir können uns nicht leisten, auch nur ein einziges Wort ihrer Unterhaltung zu verpassen.", completion = "Dichter kommen wir nicht ran, ohne uns zu verraten.", sourceObjectiveStatus = "unverified-source-field" }
quests[75922] = { id = 75922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entzündende Informationen", description = "<Shandris flüstert Euch zu.>\n\nSeht Ihr das da vorn? Die Druiden der Flamme haben etwas gefangen, das ein Hüter zu sein scheint, ein Wächter der Natur und unserem Volk heilig. Wenn ihre Macht bereits so groß ist...\n\n<Shandris schüttelt den Kopf und zeigt dann auf ein dichtes Gebüsch in der Nähe.>\n\nVersteckt Euch mit mir, dann belauschen wir die Inkarnationen und finden vielleicht heraus, was die Druiden mit dem Hüter vorhaben.", sourceObjective = "Belauscht Fyrakk und Vyranoth.", progress = "Ich werde ihre Verstärkung aufhalten, sowie sie kommt. Kümmert Euch um den Hüter!", completion = "Ich hatte Angst davor, was wir heute hier erfahren könnten, aber dies...\n\n<Shandris fasst ihren Bogen fester, um sich zu beruhigen.>\n\nDas ist schlimmer als alles, worauf wir uns hätten vorbereiten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[75923] = { id = 75923, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alarmsignal", description = "Also haben sich die Druiden der Flamme mit Fyrakk verbündet, um ihm einen Angriff auf den Smaragdgrünen Traum zu ermöglichen.\n\nSie konnten diesen Hüter fast mühelos auf die Seite der Flamme ziehen. Fyrakk muss ihre Kraft verstärken, vielleicht als Entlohnung für ihre Hilfe, in den Traum zu gelangen.\n\nWir müssen die Truppen sofort in Bewegung setzen, um jeden Druiden der Flamme auf den Dracheninseln zu finden und aufzuhalten.\n\nGeht zu Hauptmann Drine in Valdrakken und alarmiert sie. Sie wird die Drakoniden aussenden.\n\nIch werde zu Merithra gehen und mich dort um alles kümmern.", sourceObjective = "Erstattet Hauptmann Drine beim Sitz der Aspekte in Valdrakken Bericht.", completion = "Wir müssen nun auf Alexstrasza vertrauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[75932] = { id = 75932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Niffen von Loamm" }
quests[75935] = { id = 75935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeitsignatur", description = "Oh, gut, <ein Abenteurer/eine Abenteurerin>. Ich nehme an, Ihr habt schon von Pedgi gehört? Dem Komponisten?\n\nNein? Nun, dann sagt ihm das nicht.\n\nWir waren unterwegs, um für sein nächstes Lied zu recherchieren, als wir über einen Drachen namens Tempo gestolpert sind. Pedgi ist jetzt überzeugt, dass diese Drachenfrau die Einzige ist, die uns helfen kann.\n\nJa, wegen des Namens. Das reicht ihm tatsächlich schon aus.\n\nAber Tempo ist natürlich viel zu beschäftigt, um uns wirklich helfen zu können. Könntet Ihr vielleicht mit ihr reden? Vielleicht können wir ja etwas tun, um sie zu entlasten.", sourceObjective = "Erkundigt Euch, ob Tempo Pegdi bei seiner Musik helfen könnte.", progress = "Ja, er ist immer so. Aber er zahlt gut und ich hab Gelegenheit, die Welt zu bereisen.", completion = "Danke, dass Ihr mit Tempo geredet habt.\n\nPedgi kann ziemlich temperamentvoll sein, aber er hat das Herz am rechten Fleck. Meistens.", sourceObjectiveStatus = "unverified-source-field" }
quests[75936] = { id = 75936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schleim macht eben doch glücklich", description = "<Ein Wurm. Ihr kennt vielleicht jemanden, der den lieben würde.>", sourceObjective = "Bringt 1 sich windenden Wurm zu Marie Shellie in Loamm.", progress = "<Von Marie Shellie tröpfelt Schleim.>", completion = "<Marie Shellie zappelt mit ihren Fühlern und tröpfelt dabei Sabber auf Euch.>", sourceObjectiveStatus = "unverified-source-field" }
quests[75937] = { id = 75937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jetzt oder nie", description = "Glutthal ist angekommen, während Ihr unterwegs wart. Sie und ihre Verbündeten überwachen die Gegend von den Klippen aus.\n\nVielleicht solltet Ihr Euch bei ihr melden. Sie sollte nicht versuchen, die Insel alleine einzunehmen.", sourceObjective = "Trefft Euch mit Glutthal oben auf den Klippen des Morqutdorfs.", sourceObjectiveStatus = "unverified-source-field" }
quests[75938] = { id = 75938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test" }
quests[75949] = { id = 75949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Datentaktung", description = "Tempo hat Objekte aus anderen Zeitlinien erwähnt?\n\nIch habe da einen Apparat, mit dem man Melodien synchronisieren kann. Seltsamerweise scheint er die gleiche Wirkung auf die Zeitlinien in dieser Stadt zu haben. Vielleicht ein Nebeneffekt der chaotischen Temporalenergie hier?\n\nIch habe Pedgis Brille aufgewertet, um den Rhythmus der Welt zu beobachten. Damit findet man zeitlich deplatzierte Wesen leichter. Bittet ihn, Euch seine Brille zu leihen.", sourceObjective = "Benutzt Mellys Gerät in der Nähe von Objekten aus anderen Zeitlinien. Mit Pedgis Sonnenbrille sind sie leichter zu finden.", completion = "Es scheint, als wären die zeitlich deplatzierten Objekte wieder an ihrem richtigen Ort. Eine Sache weniger, um die sich Tempo kümmern muss.\n\nHmm... interessante Daten. Vielleicht werden sie später noch nützlich.\n\nEntschuldigt, dass Pedgi keine große Hilfe war. Es ist wohl am besten, seine Entschlossenheit zu stärken. Schließlich muss er das Lied schreiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[75950] = { id = 75950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Vorbild der Gerechtigkeit: Hadwin", description = "Wir sind seit einer ganzen Weile hier. Lange genug, damit ich die Gnolle in der Gegend beobachten konnte.\n\nGnolle sind immer lästig. Aber die Fäulnisgnolle hier in der Nähe der Brackenfellhöhle...\n\nDer Verfall verändert nicht nur ihre Körper. Er verzerrt auch ihren Verstand.\n\nFaulhändlerin Rottpfote ist die Schlimmste von ihnen. Sie kümmert sich nicht darum, auf wen oder was sich ihr Verfall ausbreitet: die Unwilligen ihres Volkes, Reisende, Tiere, Kinder...\n\nWenn es Gerechtigkeit in der Welt gibt, dann sollte sie ein schnelles Ende finden.", sourceObjective = "Helft Hadwin, Faulhändlerin Rottpfote zu besiegen.", completion = "Vielleicht habe ich den Mund zu voll genommen... Aber dank Eurer Hilfe mussten Rottpfote und ihresgleichen für ihre Verbrechen bezahlen.", sourceObjectiveStatus = "unverified-source-field" }
quests[75951] = { id = 75951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Vorbild der Ordnung: Talthis", description = "Ich weiß, warum Travard diesen Ort für unser Training gewählt hat. Der Verfall hier ist... chaotisch und ungeordnet.\n\nGenau das sind Tyr und die Titanen nicht!\n\nDie Gnolle in der Nähe suhlen sich im Verfall. Abstoßend.\n\nSie haben ein Gebiet übernommen, das einst von den stolzen, noblen und höflichen Tuskarr bewohnt wurde.\n\nDie Tuskarr haben darum gebeten, dass Relikte, die sie zurücklassen mussten, für sie wiederbeschafft werden. Helft mir bitte, die Gnolle zu bekämpfen und die Relikte zu finden, damit die Tuskarr ihre Rituale in Iskaara fortführen können.", sourceObjective = "Bringt Talthis 5 Tuskarrrelikte.", progress = "Die Gnolle hatten kein Recht auf diese Relikte. Sie gehören den Tuskarr.", completion = "Ich bin froh, dass wir den Tuskarr die Relikte wiederbringen konnten. Es fühlt sich gut an, einen Anschein von Ordnung über das Chaos des Verfalls zu bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[75952] = { id = 75952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Vorbild der Aufopferung: Nolaki", description = "Viele sprechen davon, wie der Verfall sich durch die Luft und die Erde verbreitet. Aber er verbreitet sich auch durch das Wasser.\n\nSchleime, die in den Bächen und Flüssen leben, scheiden Pestilenz aus. Das Wasser ist davon vergiftet. Aber wenn wir hineinwaten und den großen von ihnen töten, wird das Gift im Wasser nachlassen.\n\nVielleicht werde ich selbst dabei vergiftet. Aber ich werde ihn töten, und wenn es das Letzte ist, was ich tue. Dieser Ort bedarf einer Säuberung.\n\nSeid Ihr dabei, {name}?", sourceObjective = "Helft Nolaki, den riesigen Schleim zu besiegen.", completion = "Habt Dank, dass Ihr die kleineren Schleime aufgehalten habt, {name}. Ich konnte den großen töten, aber ich wäre immer noch dort, wenn Ihr nicht gewesen wärt.", sourceObjectiveStatus = "unverified-source-field" }
quests[75953] = { id = 75953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Vorbild des Mitgefühls: Valunei", description = "Mir schmerzt das Herz, wenn ich sehen muss, was der Verfall den Tieren hier angetan hat...\n\nIch kann nicht alle Lebewesen um die Brackenfellhöhle herum retten, aber ich wünsche mir für meine Prüfung, wenigstens einige von ihnen retten zu können.\n\nIn einer Höhle im Westen gibt es eine Bärenfamilie, die vor Kurzem verderbt wurde. Ich glaube, ich kann mich zu ihnen durchkämpfen und sie heilen. Würdet Ihr mir helfen, {name}?", sourceObjective = "Beschützt Valunei vor den Fäulnisgnollen.", completion = "Tyrs Mitgefühl für die Vrykul ist eine Inspiration für mich. Ich glaube, er hätte auch Mitgefühl mit Tieren, meint Ihr nicht auch? Sie leiden und fühlen Schmerz, wie Ihr und ich...\n\nDanke, dass Ihr mir geholfen habt, diese Bären zu retten. Auch ein wenig Mitgefühl kann eine große Wirkung haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[75954] = { id = 75954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmrisskrater-Rundflug - Herausforderung", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
