quests[75965] = { id = 75965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbotene-Insel-Eile - Umgekehrte Herausforderung", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[75966] = { id = 75966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neue Saiten aufziehen", description = "Ich schwöre, er ist nicht immer so. Nur manchmal. Öfters.\n\nIn der Regel braucht er dann ein paar Tage, um seinen Durchhänger hinter sich zu lassen, aber so viel Zeit haben wir nicht. Der Auftrag für das neue Lied gilt nicht ewig.\n\nVielleicht könntet Ihr helfen, dass es etwas schneller geht, indem Ihr Pedgis Selbstvertrauen auf die Sprünge helft?", sourceObjective = "Steigert Pedgis Selbstvertrauen.", completion = "Ich bin auf ein Problem gestoßen!", sourceObjectiveStatus = "unverified-source-field" }
quests[75970] = { id = 75970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In der falschen Zeit", description = "Ein Zeitwanderer hat ein Bärenjunges entdeckt, das in unsere heutige Zeit gestolpert ist. Es war so erschrocken, dass es weglief, bevor er es einfangen konnte!\n\nKönnt Ihr nach dem armen Ding schauen? Ihr müsst es erst beruhigen, bevor es Euch folgen wird.\n\nBringt es hierher zurück. Dann werde ich ein Temporalportal öffnen, damit es nach Hause kommt.", sourceObjective = "Rettet ein zeitverlorenes Junges und bringt es zurück in die richtige Zeit.", completion = "Überrascht davon, wer sich hinter diesem kleinen Bären verborgen hat? Da sieht man mal, dass selbst die kleinsten Lebewesen eine große Wirkung haben können!", sourceObjectiveStatus = "unverified-source-field" }
quests[75971] = { id = 75971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In der Zeit verlorenes Quietschie", description = "Wir haben eine weitere Zeitanomalie entdeckt. Ein seltsames Objekt, dessen Bedeutung selbst wir nicht verstehen.\n\nDieses Artefakt muss zurückgebracht werden, bevor es der wahren Zeitlinie und unserer Welt irreparablen Schaden zufügt.\n\nKehrt hierher zurück, wenn Ihr das Artefakt geborgen habt. Ich werde ein Portal öffnen, damit Ihr es an seinen richtigen Platz zurückbringen könnt.", sourceObjective = "Findet das zeitversetzte Spielzeug und bringt es zurück in die richtige Zeit.", progress = "Unser aller Schicksal hängt davon ab, dass wir das Artefakt in seine richtige Zeit zurückbringen.", completion = "Danke, Champion. Ihr habt Azeroth wieder einmal gerettet. Mich schaudert es bei dem Gedanken, was passiert wäre, wenn Ihr nicht eingegriffen hättet...", sourceObjectiveStatus = "unverified-source-field" }
