quests[75983] = { id = 75983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwefelsprint - Umgekehrte Herausforderung", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[75985] = { id = 75985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruht sanft, Krieger", description = "Shalkeel verdient einen würdigen Abschied.\n\nIch möchte seine Begräbnisstätte schmücken und ein paar Worte sagen. Ich weiß, dass Eure Zeit kostbar ist, aber würdet Ihr die Schaufel nehmen und seine Asche begraben, während ich die Zeremonie durchführe?", sourceObjective = "Helft Khasar bei Shalkeels Begräbnis.", progress = "Wenn ich seine Asche anfassen könnte, würde ich sie über dem Bach verstreuen, in dem er und ich als Kinder gespielt haben.", completion = "Ich wünschte, ich könnte Euch irgendwie entschädigen, aber ich habe keine Ehrenmedaillen oder legendären Waffen zu vergeben, {name}.\n\nAber Ihr sollt wissen, dass ich... diese Last heute nicht allein hätte schultern können. Ein vom Verlust ausgehöhltes Herz braucht Zeit, um sich wieder zu füllen.\n\nEuch alles Gute. Und vielen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[75986] = { id = 75986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schläge pro Minute", description = "Also gut, es gilt noch ein letztes Problem zu lösen. Wenn Euch das gelingt, haben wir uns sicher eine Audienz bei Tempo verdient!\n\nDie Ermittler haben einen weiteren Zeitschleim entdeckt. Einen viel größeren und mächtigeren Zeitschleim.\n\nWir nennen ihn Zeitschleimfein.\n\nSeine Temporalenergien werden enorm beschleunigt, was ihn besonders tödlich macht. Ich empfehle, den Metronografen mehrmals zu benutzen, um ihn zu verlangsamen, bevor Ihr es mit ihm aufnehmt.", sourceObjective = "Desynchronisiert und besiegt den Zeitschleimfein.", completion = "Ah, da seid Ihr ja. Vielen Dank für die Unterstützung bei unseren Zeitaufräumarbeiten. \n\nJetzt kann ich mit Pedgi selbst sprechen! Das ist wirklich eine große Ehre. Es fiel mir so schwer, mich zurückzuhalten, als er mich zum ersten Mal ansprach. Aber jetzt habe ich mehr als genug Zeit, um mit ihm zu sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[75987] = { id = 75987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wollomant", description = "Jaina Prachtmeer ist irgendwie an einen Zauberstab gekommen. Selbstverständlich nicht unsere Jaina, sondern ihr Kinder-Ich. Sie ist viel zu jung für solch eine Macht.\n\nWir brauchen Euch, um ihr Chaos zu beseitigen und ihr den Stab wegzunehmen.", sourceObjective = "Beseitigt 8 verwandelte Kreaturen und konfisziert Jainas Zauberstab der Massenverwandlung.", progress = "Jaina darf nicht mit Magie herumspielen, bis sie alt genug ist, um verantwortungsvoll damit umzugehen. Ich vertraue darauf, dass Ihr dem ein Ende setzt, bevor die Situation bedrohlich wird.", completion = "Danke, dass Ihr dieses Chaos beseitigt habt. Mich schaudert es bei dem Gedanken, was passieren würde, wenn sie mit solchen... Tendenzen aufwächst.", sourceObjectiveStatus = "unverified-source-field" }
quests[75988] = { id = 75988, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glücks-Hearthstone-Karte", description = "Ich hatte gerade eine Partie Hearthstone mit meinem Vater gespielt, als ich irgendwie hier gelandet bin. Dann flogen ein paar Drachenwelpen mit meiner Glückskarte davon, um sie ihrem... \"Kartentornado\" hinzuzufügen?\n\nUnd dann sagten alle Erwachsenen, dass ich sofort nach Hause gehen soll. Aber ohne meine Glückskarte kann ich nicht nach Hause gehen!\n\nKönntet Ihr mir bitte helfen? Ich verspreche auch, dass ich nach Hause gehe, wenn Ihr sie mir zurückbringt!", sourceObjective = "Tötet den verzauberten Kartenschwarm und sichert Anduins Glücks-Hearthstone-Karte.", progress = "Es geht mir schon etwas besser. Bob hat mir etwas Saft gegeben. Aber ich weiß immer noch nicht, was los ist.\n\nWas ist das für ein Ort? Wie bin ich hierher gekommen?", completion = "Ihr habt meine Glückskarte tatsächlich zurückbekommen? Vielen, vielen lieben Dank, {name}!\n\nDaran werde ich mich immer erinnern. Ich bin jetzt bereit, nach Hause zu gehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[75989] = { id = 75989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parade des schwarzen Prinzen", description = "Hier haben sich fünf verschiedene Portale gleichzeitig geöffnet, und aus jedem ist dieselbe Person herausgetreten.\n\nSomit haben wir hier jetzt ein Gasthaus voller Furorions, die alle unterschiedlichen Alters sind, unterschiedliche Dinge in ihrem eigenen Leben zu tun haben und sich unentwegt gegenseitig die Schuld für ihre Probleme geben.\n\nWir müssen sie alle in ihre Zeit zurückbringen, bevor sie zu viel Ärger machen.", sourceObjective = "Schickt jeden einzelnen Furorion durch sein entsprechendes Temporalportal zurück in seine Zeit.", completion = "Gut, dass das geregelt ist. Stellt euch vor, wenn unser Furorion vorbeigekommen wäre! Ich glaube nicht, dass mein Gasthaus SECHS von denen hätte bewältigen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[75990] = { id = 75990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liebe unter einem schwierigen Stern", description = "Wir haben vor Langem eine Zeitstörung entdeckt. Jemand hat Illidan geholfen, Tyrande zu bezirzen und uns damit alle der Brennenden Legion ausgeliefert!\n\nMalfurion ist so verzweifelt, dass er nicht mehr schlafen kann. Er hat keine Ahnung, wie wir sie wieder auf unsere Seite ziehen können.\n\nWir brauchen Eure Hilfe, bevor die Zeitlinie zerstört wird.", sourceObjective = "Helft Malfurion, Tyrandes Zuneigung in Val'sharah zu gewinnen.", progress = "So brutal es auch sein kann... Herzschmerz ist wichtig, um uns zu dem zu machen, was wir sind. Auch wenn das, was wir sind, nicht immer... schön ist.", completion = "Wenn wir doch nur Illidan sein Glück mit Tyrande eine kleine Weile länger hätten gönnen können. Ich fand die beiden immer so süß zusammen!\n\nAber wir müssen alle unseren Teil dazu beitragen, dass die Zeit ordnungsgemäß verläuft!", sourceObjectiveStatus = "unverified-source-field" }
quests[75991] = { id = 75991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was hätte sein können", description = "Vor einiger Zeit ist hier eine geheimnisvolle fremde Person durch eines dieser Zeitportale aufgetaucht.\n\nSie sagte mir, dass es in der Nähe eine Bedrohung gibt, bei der Eure Hilfe benötigt wird. Es geht um eine Art Tarnvorrichtung, aber es könnte Euch vielleicht nicht gefallen, was Ihr seht, wenn sie deaktiviert wird.\n\nAllerdings könnte es sein, dass Euch die fremde Person auch nicht sonderlich gefällt.", sourceObjective = "Helft einer alternativen Version Eurer selbst, einen gemeinsamen Feind zu bezwingen.", completion = "Oh, gut, Ihr habt es beide wohlbehalten zurückgeschafft. Schön, dass Ihr Eure Differenzen beilegen konntet.", sourceObjectiveStatus = "unverified-source-field" }
quests[75996] = { id = 75996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer Gewicht in Gold" }
quests[75998] = { id = 75998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knusprig und knackig", description = "<Ihr habt diese Art von Käfer in der Nähe der Ställe in Loamm gesehen. Vielleicht weiß der Stallmeister mehr über sie?>", sourceObjective = "Bringt den knusprigen Käfer zu Vanndual in Loamm.", progress = "Ein Kirschkäfer!", completion = "Kirschkäfer sind Garys Lieblingshäppchen, nicht wahr Gary?\n\n<Gary wackelt mit den Fühlern.>\n\nWenn Ihr mehr davon findet, bringt sie unbedingt mit!", sourceObjectiveStatus = "unverified-source-field" }
quests[76004] = { id = 76004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefe Schnitte", description = "<Ihr findet eine weggeworfene Tiefenschinderklaue. Ihr habt gesehen, wie einige Niffen sie als Waffe benutzen.>", sourceObjective = "Bringt 1 Tiefenschinderklaue zu Flammenmeister Crubus in Loamm.", progress = "Vorsicht, die sind scharf.", completion = "Diese Klauen haben für uns die perfekte Größe, um sie als Waffen zu verwenden... Sie sind allerdings schwer zu bekommen.\n\nWenn Ihr noch mehr davon findet, nehme ich sie Euch ab!", sourceObjectiveStatus = "unverified-source-field" }
quests[76014] = { id = 76014, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lebendige Statue" }
quests[76015] = { id = 76015, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisernes Herz" }
quests[76016] = { id = 76016, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der lebende Bohrer" }
quests[76026] = { id = 76026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersuchung des Turms", description = "Seht Euch nur diese Felsformationen an! Besser als das werden Untersuchungen nicht.\n\nDieser Turm steht hier seit Ewigkeiten. Der schwarze Drachenschwarm hat hier einige ziemlich düstere Sachen angestellt, aber deshalb sind wir nicht hier. Nachdem die Drachen verschwanden, fand eine Gruppe von Niffenbanditen Unterschlupf in den Ruinen und räumte alles von Wert aus. Aber sie ließen eine Menge Müll zurück.\n\nStellt Euch nur vor, was wir durch einen Haufen Müll alles über die Niffen erfahren können, sobald wir anfangen zu graben!", sourceObjective = "Sprecht mit Roska, um mit der Ausgrabung zu beginnen, und grabt dann Artefakte um den Turm aus.", completion = "<Roska lacht laut auf.>\n\nOh, dahinter muss ja eine verrückte Geschichte stecken!", sourceObjectiveStatus = "unverified-source-field" }
quests[76027] = { id = 76027, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flattern und Schreien" }
quests[76029] = { id = 76029, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragon Isles Supplies", sourceObjective = "Sprecht mit Mimuup in Loamm.", completion = "Vielen Dank für all Eure Hilfe hier!", sourceObjectiveStatus = "unverified-source-field" }
quests[76030] = { id = 76030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fliegendes Schlängeln", description = "Ah, hallo!\n\nEs spricht sich herum, dass wir Eure anhaltende Unterstützung haben. Darum haben wir da etwas für Euch. Trefft mich in Loamm, damit ich es Euch geben kann!\n\nGrüße,\nHarlowe Marl", sourceObjective = "Sprecht mit Harlowe Marl in Loamm.", completion = "Es ist gut, Euch hier zu haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[76032] = { id = 76032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Müll verborgen", description = "<Diese Drachenstatue ähnelt anderen, die in der Region gefunden wurden, aber sie ist völlig mit Farbe beschmiert.\n\nGlotzaugen, Stinklinien, Schnurrhaare und alle möglichen unhöflichen Kritzeleien überziehen den ansonsten beeindruckenden Stein. Die Farbe wirkt alt und blättert hier und da ab, ist aber bei Weitem nicht so alt wie die Statue selbst.\n\nRoska wird sich das ansehen wollen!>", sourceObjective = "Grabt die verschandelte Drachenstatue vorsichtig aus.", completion = "Ich sag's Euch, diese Niffenbanditen hatten echt Sinn für Humor!", sourceObjectiveStatus = "unverified-source-field" }
quests[76033] = { id = 76033, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelswaldtour - Herausforderung", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
