quests[76067] = { id = 76067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterschrieben, versiegelt und selbst abgeliefert", sourceObjective = "<Posti scheint von Euch hochgehoben werden zu wollen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[76072] = { id = 76072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scharlachrote Schatten", description = "Ich brauche Eure Hilfe, {name}. Ich dachte, ich hätte endlich so etwas wie inneren Frieden erreicht. Wenn meine Sünden doch unverzeihlich sind, hätte ich doch wenigstens mit meiner geliebten Familie wiedervereint werden können. Doch... der Geist meiner Frau ist nicht hier, als hätte sie nie existiert.\n\nSchlotternächte lockt die Schatten, die das Kloster heimsuchen, aus der Finsternis hervor. Gefangen in der Vergangenheit irren sie über das Gelände und erleben ihre Alpträume immer wieder aufs Neue.\n\nMit etwas Glück kann einer von ihnen uns womöglich sagen, was mit ihr geschah.", sourceObjective = "Sucht bei den Schatten am Scharlachroten Kloster nach Spuren.", completion = "<Sire Thomas ist in Gedanken versunken und erschrickt, als Ihr Euch nähert.>\n\n{name}! Verzeiht mir, dass ich vorhin einfach davongelaufen bin. Es gibt... Erinnerungen, die ich nie wieder durchleben möchte.\n\nWie es scheint, wissen die grausamen Schatten genau, wie sie ihren Finger in unsere Wunden legen müssen.\n\nKommt, ich weiß, wo wir als Nächstes nachsehen sollten.", sourceObjectiveStatus = "unverified-source-field" }
quests[76073] = { id = 76073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine ernste Sache", description = "Am Ende dieses Weges befindet sich eine Brunnenterasse. Vor der Zerstörung Lordaerons durch die Geißel nahm ich meine geliebte Suzannah oft mit dorthin. Ich weiß noch, welche Gewissheit ich damals spürte. Gewiss meiner selbst, des Lichtes... ihr und meiner Kinder.\n\nIch frage mich, wann mein Pfad mich ins Dunkel führte.\n\nWenn uns ein Schatten hier helfen kann, muss er am Brunnen sein.", sourceObjective = "Untersucht den Brunnen des Klosters.", completion = "<Suzannah schweigt eine Weile lang.>\n\nEs ist noch gar nicht so lange her, dass mein Mann Thomas mich angefleht hat, nach Kalimdor zu fliehen, um der Geißel zu entgehen. Er war in dieser Nacht nicht ins Bett gekommen, sondern hielt stumm Wache, um uns zu beschützen. Die Furcht in seiner Stimme, die Verzweiflung in seinen Augen jagten mir Angst ein...\n\n<Suzannah zeichnet sanft eine Linie auf ihrer Handfläche nach und umklammert sie dann fest.>\n\nIch werde ihn nicht verlassen. Diesmal nicht. Nie wieder.", sourceObjectiveStatus = "unverified-source-field" }
quests[76074] = { id = 76074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr des kopflosen Reiters", description = "Thomas hat sich in das Scharlachrote Kloster zurückgezogen. Seine Bindung an diesen Ort ist ausgeprägt, selbst in seiner derzeit verderbten Gestalt.\n\nEuer Name lautet {name}, oder? Mein Mann hat darauf vertraut, dass Ihr ihm helft. Deshalb muss ich Euch ebenfalls darum bitten. Ich habe vor, die Verfolgung aufzunehmen, aber ich kann ihn nicht allein retten.\n\nWerdet Ihr mich begleiten?", sourceObjective = "Verwendet den Dungeonbrowser, um den Dungeon \"Der kopflose Reiter\" zu finden, und besiegt den kopflosen Reiter.", completion = "Einmal mehr wurde ich vor dem Wahnsinn gerettet. Wie kann ich Euch je danken?", sourceObjectiveStatus = "unverified-source-field" }
quests[76075] = { id = 76075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine gespenstische Nachricht", description = "Entschuldigt bitte, Ihr seid doch {name}, nicht wahr? Ihr habt Euch in letzter Zeit einen gewissen Namen gemacht, sowohl bei den Lebenden als auch bei den Toten.\n\nIch besitze den Folianten von Thomas Thomson. Seit Jahren schon steht er in meiner Bibliothek als Erinnerung an Zeiten, die wir nicht vergessen dürfen. Ihr könnt Euch ja vielleicht vorstellen, wie überrascht ich war, als er von selbst zu Boden fiel und sich beim Aufprall eine Seite mit nur einem Namen drauf öffnete.\n\nEurem Namen, {name}.\n\nWenn Thomas' Geist versucht, mit Euch in Kontakt zu treten, solltet Ihr diesen Folianten mitnehmen. Vielleicht wartet er im Scharlachroten Kloster auf Euch?", sourceObjective = "Sucht nach Thomas Thomson in der Nähe des Scharlachroten Klosters in Tirisfal.\n\nBereitgestellter Gegenstand:", completion = "Endlich, {name}. Ich wusste, Ihr würdet kommen.\n\nIch benötige wieder einmal Hilfe, und ein Abenteurer Eures Kalibers käme mir gerade recht.", sourceObjectiveStatus = "unverified-source-field" }
quests[76076] = { id = 76076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleinigkeiten", description = "Ein paar übereifrige Welpen haben einige kleine Objekte aus der Geschichte entführt. Kleine Dinge haben manchmal große Wirkung. Ich habe den Welpen zwar doppelte Hausarbeit aufgebrummt, aber ich brauche jetzt jemanden, der diese Felsen wieder zurück an ihren richtigen Ort in der Geschichte bringt.\n\nJa, ich weiß. Felsen?! Aber die müssen zurück.", sourceObjective = "Bringt die eisigen Felsen zurück nach Lordaeron.", completion = "Danke, dass Ihr das erledigt habt, {name}. Die Zeitwege unter Kontrolle zu halten, ist nicht immer spaßig oder ruhmreich, und manchmal muss man Dinge tun, die man lieber vermeiden würde, aber die wahre Zeitlinie muss weiterlaufen!", sourceObjectiveStatus = "unverified-source-field" }
quests[76081] = { id = 76081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lügner des Geistes" }
quests[76083] = { id = 76083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aberrus, Schmelztiegel der Schatten: Echos des Erdwächters", description = "Ich spüre eine dunkle Präsenz irgendwo in diesen Hallen... etwas seltsam vertrautes. Vielleicht gibt es sich zu erkennen, während wir die vielen Kammern von Aberrus erkunden. Wenn Ihr Hinweise zu diesem lauernden Bösen findet, erhalten wir vielleicht leichter Zugang zu den Tiefen unter uns.", sourceObjective = "Sammelt 3 Foliantenn des Erdwächters vom Echo von Neltharion in Aberrus, Schmelztiegel der Schatten auf dem Schwierigkeitsgrad 'Normal'.", progress = "Das Wissen, dass wir hierdurch erhalten, könnte uns einen direkteren Zugang in die Tiefen von Aberrus eröffnen.", completion = "Damit sollten wir leichter in die Tiefen von Aberrus hinabsteigen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[76084] = { id = 76084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostfeuerfinesse" }
quests[76085] = { id = 76085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aberrus, Schmelztiegel der Schatten: Echos des Erdwächters", description = "Ich spüre eine dunkle Präsenz irgendwo in diesen Hallen... etwas seltsam vertrautes. Vielleicht gibt es sich zu erkennen, während wir die vielen Kammern von Aberrus erkunden. Wenn Ihr Hinweise zu diesem lauernden Bösen findet, erhalten wir vielleicht leichter Zugang zu den Tiefen unter uns.", sourceObjective = "Sammelt 3 Foliantenn des Erdwächters vom Echo von Neltharion in Aberrus, Schmelztiegel der Schatten auf dem Schwierigkeitsgrad 'Heroisch'.", progress = "Das Wissen, dass wir hierdurch erhalten, könnte uns einen direkteren Zugang in die Tiefen von Aberrus eröffnen.", completion = "Damit sollten wir leichter in die Tiefen von Aberrus hinabsteigen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[76086] = { id = 76086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aberrus, Schmelztiegel der Schatten: Echos des Erdwächters", description = "Ich spüre eine dunkle Präsenz irgendwo in diesen Hallen... etwas seltsam vertrautes. Vielleicht gibt es sich zu erkennen, während wir die vielen Kammern von Aberrus erkunden. Wenn Ihr Hinweise zu diesem lauernden Bösen findet, erhalten wir vielleicht leichter Zugang zu den Tiefen unter uns.", sourceObjective = "Sammelt 3 Foliantenn des Erdwächters vom Echo von Neltharion in Aberrus, Schmelztiegel der Schatten auf dem Schwierigkeitsgrad 'Mythisch'.", progress = "Das Wissen, dass wir hierdurch erhalten, könnte uns einen direkteren Zugang in die Tiefen von Aberrus eröffnen.", completion = "Damit sollten wir leichter in die Tiefen von Aberrus hinabsteigen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[76101] = { id = 76101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefer, schneller, weiter", description = "Seit die Höhle aufgerissen wurde, sind eine Menge Oberländer hier angekommen! \n\nEine freundliche Geflügelte namens Vaskarn hat uns besonders geholfen. Sie hat die Rüstung der Wachen und die Waffen der Monsterjäger verstärkt.\n\nSie wird wirklich nützlich sein, wenn Ihr hier in Zaralek noch mehr riesige Monster erlegen wollt!", sourceObjective = "Sprecht mit Vaskarn.", completion = "Ihr habt ordentliche Ausrüstung! Wollen wir mal sehen, was wir daraus machen können?", sourceObjectiveStatus = "unverified-source-field" }
quests[76103] = { id = 76103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldet Euch im Handelsposten", description = "<Das Funkeln eines entfernten Objekts zieht Eure Aufmerksamkeit auf sich. Ihr erinnert Euch plötzlich, dass Ihr Devisen für den T&W-Handelsposten sammeln müsst.>", sourceObjective = "Kehrt zum Handelsposten zurück und nehmt Eure Händlerdevisen aus der Truhe des Sammlers.", completion = "Ich hoffe, Euch gefällt die monatliche Sammlung neuer und exotischer Waren, {name}.", sourceObjectiveStatus = "unverified-source-field" }
