quests[76122] = { id = 76122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf ist eine Belohnung in sich", description = "Ah, {name}. Gut, Euch zu sehen.\n\nTheldren und ich haben dank Eurer Mühen viel gelernt. Aber es lauert immer etwas in der Nähe, das die natürliche Ordnung der Dracheninseln stören will.\n\nIch muss Euch bitten, Eure Freunde zu versammeln und jene aufzuhalten, die uns und unserer Lebensweise hier auf den Inseln schaden wollen.", sourceObjective = "Schließt 5 Dungeons von Dragonflight auf dem Schwierigkeitsgrad 'Heroisch' ab.", completion = "Vielen Dank, {name}!\n\nIhr inspiriert uns alle immer wieder.", sourceObjectiveStatus = "unverified-source-field" }
quests[76140] = { id = 76140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämmerung der Unendlichkeit", completion = "Ganz recht, ich bin es! Chromie aus der Zukunft! Ich freue mich, Euch zu sehen. Wiederzusehen.\n\nIch kann nicht zu viel darüber preisgeben, wann ich herkomme oder warum ich hier bin. Zum Schutz der Zeitwege und so, Ihr versteht. Aber ich weiß genau, was geschehen wird und wie wir es verhindern können!" }
quests[76141] = { id = 76141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sand im Getriebe", description = "Also die Zeitwege, ja? Die sind VÖLLIG falsch ausgerichtet. Und Ihr wisst, wie sehr wir Bronzenen das hassen! Wir müssen sie also mit diesen temporalen Stundengläsern neu ausrichten. Werft sie einfach überall in Grenze des Äons ab.\n\nAber Ihr kennt mich, ich kann auch nicht untätig bleiben! Ich werde also in der Nähe selbst ein Stundenglas platzieren. Trefft mich dort, wenn Ihr alles erledigt habt.", sourceObjective = "Platziert die temporalen Stundengläser überall in den Wandernden Sande in Thaldraszus.", completion = "<Chromie hört mit großen Augen aufmerksam zu, als Ihr erklärt, was Ihr macht.>\n\nIch? Aus der Zukunft? Sie zählt zu den drei vertrauenswürdigsten Leuten überhaupt!\n\nAber das ergibt alles keinen Sinn. Warum sollte sie Euch bitten, die Zeitwege zu stören, um damit Nozdormu zu helfen? Davon würde er höchstens Migräne bekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[76142] = { id = 76142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit geborgter Zeit", description = "Bringt mir etwas zeitverlorene Essenz. Die Kreaturen hier sind randvoll von dem Zeug.\n\nBringt sie zur Strecke und sammelt dann mithilfe dieses Epochenextraktors ihre Essenz. Die brauchen wir für den nächsten Schritt!\n\nUnd ja, das wird ein mehrstufiger Prozess. Ihr wisst doch, wie verrückt es wird, wenn man einmal anfängt, an der Zeit herumzupfuschen!", sourceObjective = "Sammelt zeitverlorene Essenz von getöteten zeitverlorenen Kreaturen in den Wandernden Sanden.", progress = "Was haben wir denn hier? Zeitverlorene Essenz? Ein Epochen...extraktor?", completion = "Ich weiß nicht, wozu das alles gut sein soll, aber ich werd schon einen Nutzen dafür finden. Wir wollen ja nichts verschwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[76143] = { id = 76143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chrom-ich?", description = "Eine Folge Eurer \"Zeitneuausrichtung\" war, dass sie offenbar... mich beschwört hat? Na ja, Versionen von mir aus anderen Zeitlinien.\n\nIch habe noch nie so viele Chromies auf einem Haufen gesehen! Sie mögen ja alle herzallerliebst sein, aber sie bringen die örtlichen Zeitwege völlig durcheinander.\n\nWir müssen sie erstmal dingfest machen, um ihre Zeitsignaturen zu synchronisieren. Vielleicht können sie uns dann verraten, was hier eigentlich los ist!", sourceObjective = "Setzt alternative Chromies in Zeitstasis fest.", progress = "Es ist nicht sehr nett, andere Chromies festzusetzen, aber wir müssen ihre Zeitsignaturen so schnell wie möglich synchronisieren!\n\nIch bin sicher, sie haben Verständnis dafür. Das hätte ich auch! Vermutlich...", completion = "<Chromie lauscht staunend Eurem Bericht darüber, was die alternativen Chromies Euch erzählt haben.>\n\nOh nein. Wir wurden reingelegt! Diese Chromie aus der Zukunft ist überhaupt keine Zukunftschromie. Sie ist ein Ich aus einer alternativen Zeitlinie, genau wie die anderen Chromies!\n\nWarum sollte sie Euch belügen?", sourceObjectiveStatus = "unverified-source-field" }
quests[76144] = { id = 76144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morchie-Chaos", description = "Wir müssen dieser \"Zukunftschromie\"-Geschichte auf den Grund gehen. Wo ist dieser Drache nur? Sie muss sich erklären!\n\nFangen wir mit der Untersuchung eines ihrer temporalen Stundengläser an. Vielleicht finden wir dort einen Hinweis.", sourceObjective = "Untersucht die falsche Zukunftschromie", progress = "Oh, diese Morchie! Ich bin noch nie einer solch hinterhältigen, fiesen Chromie begegnet.", completion = "Wenigstens haben wir Morchies Komplizen aufgehalten. Diese ewigen Drachen machen immer nur Ärger.\n\nAber wir können nicht ruhen, bis Morchie selbst gefangen wurde und in ihre EIGENE lausige Zeitlinie zurückgeschickt wurde!", sourceObjectiveStatus = "unverified-source-field" }
quests[76145] = { id = 76145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer ist diese Chromie?", description = "Morchie hat sich nicht einfach wegteleportiert, sie hat auch alle anderen Chromies mitgenommen! Ich habe da einen schlimmen Verdacht...\n\nWir müssen ihr folgen und sie einfangen. Und befragen! Ich will wissen, was sie vorhat.", sourceObjective = "Fangt und befragt Morchie.", completion = "Wir können jetzt nicht aufgeben! Noch bleibt Zeit, den Tempel zu retten und diese Ewigen ein für alle mal zu schlagen. Wir dürfen sie die wahre Zeitlinie nicht kontrollieren lassen.\n\nUnd ich werde auf keinen Fall zulassen, dass sie Nozdormu in diesen schrecklichen Murozond verwandeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[76146] = { id = 76146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämmerung des Ewigen: Chronolord Deios", description = "Hinter all dem muss Chronolord Deios stecken. Als Anführer der Ewigen hat er diese Invasion sicher angeführt. Ich wette, Morchie arbeitet auch für ihn.\n\nGehen wir zum Bronzetempel! Wir müssen Deios aufhalten, bevor er die wahre Zeitlinie zerstört.", sourceObjective = "Besiegt Chronolord Deios.", completion = "Das verdanken wir alles Euch, {name}. Ihr habt uns vor der schrecklichen Dämmerung des Ewigen bewahrt.\n\nDoch vor allem habt Ihr mich vor einem Schicksal bewahrt, das ich für unausweichlich hielt. Mein ewiger Dank gebührt Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[76147] = { id = 76147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurückspulen und Wiedergutmachen", description = "<Ihr spürt eine mächtige Zeitenergie von dem Relikt ausgehen, das Ihr nach dem Kampf mit Chronolord Deios geborgen habt. Zwei nach links zeigende Pfeile scheinen darauf eingraviert zu sein. Ihr solltest es Nozdormu zeigen.>", sourceObjective = "Gebt das Zeitrelikt Nozdormu im Temporalen Konflux in Thaldraszus.", progress = "Ich spüre ein mächtiges Relikt in Eurem Besitz. Würdet Ihr mir erlauben, es zu untersuchen?", completion = "Chronormu hat erwähnt, dass sie nach Eurem Kampf mit Morchie ein Relikt fand. Das Gerät ließ die Zeit schneller voranschreiten.\n\nDieses Relikt scheint eine ähnliche Macht zu haben, nur lässt es die Fäden der Zeit zurückspulen und zu einem früheren Zeitpunkt zurückkehren.\n\nIch werde es verwahren, {name}. Ein solches Gerät sollte besser nicht in falsche Hände geraten.", sourceObjectiveStatus = "unverified-source-field" }
quests[76155] = { id = 76155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Wolf unter Schafen", description = "Danke, dass Ihr mir geholfen habt.\n\nAber ich will unserer neuen... Mentorin gegenüber nicht undankbar sein. Tut mir einen Gefallen, füllt Madame Schattens Seelenstein auf eine andere Art. Wir sollten unsere Lehrerin nicht auf die Probe stellen, aber sie muss sich mein Vertrauen erst noch verdienen.", sourceObjective = "Helft Oman, Madame Schattens Seelenstein auf der Dunkelmond-Insel zu füllen.", completion = "Ah, der verlorene {class} kehrt zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[76158] = { id = 76158, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Temporalgespinst", description = "Das Temporalgespinst nimmt die Form empfindlicher, seidener Stränge an, die in der Nähe der uralten Erinnerungen eines Rufers stärker zu werden scheinen.\n\nEinem Rufer dabei zu helfen, Temporalvestigien zu finden, scheint die Entschlossenheit dieser Gewebe zu stärken, wodurch sie sich eng mit den uralten Erinnerungen verbinden können.", sourceObjective = "Stärkt das Temporalgespinst durch Gruppeninhalte auf den Dracheninseln.\n\nDas Gespinst wird nur in einer Gruppe und in der Nähe eines Besitzers uralter Erinnerungen stärker.", completion = "Danke für die Hilfe. Erlaubt mir, die Bindung dieser Temporalstränge zu vervollständigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[76159] = { id = 76159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldet Euch im Handelsposten", description = "<Das Funkeln eines entfernten Objekts zieht Eure Aufmerksamkeit auf sich. Ihr erinnert Euch plötzlich, dass Ihr Devisen für den T&W-Handelsposten sammeln müsst.>", sourceObjective = "Kehrt zum Handelsposten zurück und nehmt Eure Händlerdevisen aus der Truhe des Sammlers.", completion = "Ich hoffe, Euch gefällt die monatliche Sammlung neuer und exotischer Waren, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[76162] = { id = 76162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fehlendes Mojo", description = "Ich habe Zauber geübt und plötzlich bin ich hier und mein Mojo is' davongerannt!\n\nWeit kann es nich' sein. Könntet Ihr für mich danach such'n? Ich brauch 'nen kräftigen Schluck.", sourceObjective = "Findet Vol'jins vermisstes Mojo.", progress = "Habt Ihr mein Mojo gefund'n?", completion = "Danke für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[76163] = { id = 76163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas weniger teuflisch", sourceObjective = "Trefft Oman in Beutebucht.", completion = "Es freut mich, dass Ihr gekommen seid, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[76164] = { id = 76164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bovans letzte Hoffnung", description = "Wenn Bovan nicht hier ist, könnten die Nokhud ihn überall hingebracht haben. Wir haben vielleicht noch eine Möglichkeit, ihn zu finden, auch wenn sie nicht sehr aussichtsreich ist.\n\nWir haben immer noch Bovans Halskette. Einer der Mystiker der Ohn'ir könnte damit vielleicht seinen Standort wahrsagen. Ich habe von diesem Ritual bisher nur gehört, ich habe also keine Ahnung, ob es funktioniert.\n\nGeht zu den Quellen von Ohn'iri und sucht nach Boku. Ich bin sicher, es wird ihm eine Freude sein, uns zu helfen.\n\nBaine und ich werden dafür sorgen, dass die Tauren, die wir gerettet haben, sicher zurückkehren. Wir treffen Euch dann bei den Quellen von Ohn'iri.", sourceObjective = "Findet Boku bei den Quellen von Ohn'iri.", sourceObjectiveStatus = "unverified-source-field" }
quests[76167] = { id = 76167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ort der Zuflucht", description = "Als Erstes müssen wir die anderen einholen, die geflohen sind, während Bovan sie verteidigt hat. Hoffentlich sind Bovan und die anderen Krieger wieder zu ihnen gestoßen.\n\nDiese Tomul sagt, dass die Tauren vermutlich in einem verlassenen Dorf im Südosten Zuflucht gesucht haben.\n\nIhre Argumente sind schlüssig, aber das wäre auch der perfekte Ort für eine Falle.\n\n{name}, ich weiß, dass Ihr Euch für sie verbürgt, also werde ich ihr vorerst vertrauen.\n\nHoffen wir, dass dieses Vertrauen gerechtfertigt ist.", sourceObjective = "Trefft Baine und Tomul in Toghusuq.", sourceObjectiveStatus = "unverified-source-field" }
quests[76168] = { id = 76168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ort der Zuflucht", description = "Als Erstes müssen wir die anderen einholen, die geflohen sind, während Bovan sie verteidigt hat. Hoffentlich sind Bovan und die anderen Krieger wieder zu ihnen gestoßen.\n\nDiese Tomul sagt, dass die Tauren vermutlich in einem verlassenen Dorf im Südosten Zuflucht gesucht haben.\n\nIhre Argumente sind schlüssig, aber das wäre auch der perfekte Ort für eine Falle.\n\n{name}, ich weiß, dass Ihr Euch für sie verbürgt, also werde ich ihr vorerst vertrauen.\n\nHoffen wir, dass dieses Vertrauen gerechtfertigt ist.", sourceObjective = "Trefft Baine und Tomul in Toghusuq.", sourceObjectiveStatus = "unverified-source-field" }
quests[76169] = { id = 76169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Leuchten im Dunkeln", description = "Verflixt noch eins! Der Brummige hat sich schon wieder verdrückt. Er ist für diesen Posten eingeteilt, aber er ist nie hier!\n\nIch habe aus der Höhle in der Nähe sein Geschrei gehört. Er muss versucht haben, sich dort zu verstecken.\n\nNehmt meine Fackel und geht zur Kaltschattenhöhle. Findet den Brummigen und die Flaschen mit Trunk der Furchtloser Funke, die er gestohlen hat. Meinetwegen kann er sich irgendwo verkriechen, aber die Getränke überlasse ich ihm nicht!", sourceObjective = "Findet den \"Brummigen\" Paeton Berncort und bringt 8 Flaschen Trunk der Furchtloser Funke zurück.", progress = "Habt Ihr den \"Brummigen\" Paeton Berncort und die Flaschen mit Trunk der Furchtloser Funke gefunden, die er mitgenommen hat?", completion = "Ich habe nicht damit gerechnet, dass der \"Brummige\" den Mut aufbringen würde, zurückzukehren, aber wenigstens habt Ihr den Trunk wiedergefunden. \n\nWir stoßen an und wünschen ihm in der Höhle Glück.", sourceObjectiveStatus = "unverified-source-field" }
quests[76171] = { id = 76171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Fußspuren von Tyr", description = "Es ist Tradition, dass die Rekruten die Ausrüstung von Tyrs Wache erhalten, kurz bevor sie zur letzten Prüfung ihrer Ausbildung aufbrechen.\n\nDas sollte normalerweise höchstrangige Offizier der Wache übernehmen, aber... Es wäre mir eine Ehre, wenn stattdessen Ihr ihnen ihren Schild und Wappenrock für ihre letzte Prüfung überreicht.", sourceObjective = "Verteilt die Ausrüstung an Tyrs Wache.", progress = "Wappenrock und Schild sind wichtige Symbole der Hingabe eines neuen Rekruten für Tyrs Wache.", completion = "Danke, {name}. Unsere Rekruten sollten jetzt bereit für ihre letzten Prüfungen sein.\n\nGeht zu ihnen. Ich bin sicher, sie werden Eure Führung beim Abschluss ihrer Missionen begrüßen.", sourceObjectiveStatus = "unverified-source-field" }
quests[76176] = { id = 76176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erste Schritte", description = "Machen wir uns also daran, die Scheibe zu finden. Ich kann nicht fassen, dass wir nach Tausenden von Jahren Tyrs Rückkehr bezeugen werden. Noch weniger, dass ich eine Rolle darin spiele.\n\nWir sollten uns drinnen mit Chromie und Eternus treffen. Sie werden uns sagen, was wir als Nächstes tun sollten.", sourceObjective = "Trefft Chromie und Eternus in Tyrhold.", completion = "Ihr seid gerade rechtzeitig zurück, {name}! Wir haben herausgefunden, wo Tyrs Wache die Leuchtfeuer platzieren muss. Meldet Euch bei Eternus, wir werden bereit sein, wenn Ihr es seid!", sourceObjectiveStatus = "unverified-source-field" }
quests[76194] = { id = 76194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein finsteres Omen", description = "Tyrande hatte den Verdacht, dass hier im Teufelswald etwas Schreckliches vor sich geht... und sie hatte recht.\n\nIhre Priesterin Kaylessa wurde hergeschickt, um den Mondbrunnen von der Teufelsverderbnis, die dieses Land plagt, zu reinigen, um zurückzuerobern, was uns zusteht.\n\nJetzt haben wir eine unserer Schwestern verloren und der Mondbrunnen ist immer noch verderbt. Das dürfen wir nicht zulassen. Wir werden beenden, was Kaylessa begonnen hat, und den Mondbrunnen heilen.\n\nArko'narin hat eine Vorgeschichte mit diesem Ort. Ich werde sie bitten, Euch zu erklären, warum wir hier sind.", sourceObjective = "Sprecht mit Arko'narin Sternschatten, um mehr über Jaedenar zu erfahren.", progress = "Habt Ihr schon mit Arko'narin gesprochen, {class}?", completion = "Es ist Zeit zu zeigen, was Ihr könnt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[76195] = { id = 76195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbnis vertreiben", description = "Ich kann Euch nicht genug für Eure Hilfe hierbei danken, {name}. Als Nari mir von dieser Mission erzählte, wusste ich, dass ich hier sein muss, um ihr zu helfen.\n\nEs scheint, dass mein Können gebraucht wird, so, wie ich es mir gedacht hatte. Die Magie hier ist faul und verdorben. Sie muss eingedämmt werden.\n\nBitte, nehmt dieses Buch und lest die Beschwörungsformel darin, nachdem Ihr die Satyrn bei Jaedenar zur Ruhe gebettet habt.\n\nJaedenar muss nicht länger ein Ort des Todes und Verfalls sein.", sourceObjective = "Benutzt den Folianten des Beschwörers bei 6 teufelsberührten Satyrleichen.", completion = "Diese Satyrn... waren Schildwachen? Wer auch immer diese Gräueltat begangen hat, wird dafür bezahlen!", sourceObjectiveStatus = "unverified-source-field" }
quests[76196] = { id = 76196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnade oder Elend", description = "Dieser Ort... war einst sehr wichtig für meine Familie. Deswegen war ich bereit herzukommen, und dasselbe gilt für Lysander.\n\n<Arko'narin blickt kurz herüber zu Lysander und sieht dann Euch wieder an.>\n\nSelbst nach dem Schrecken von Teldrassil tut mein Bruder immer noch alles in seiner Macht Stehende, um anderen zu helfen. So wie Ihr, {name}.\n\nKommt. Wir müssen die Bedrohung ausschalten, die diese machthungrigen Idioten darstellen. Ich glaube, Ihr seid genau <der/die> richtige Kaldorei für die Aufgabe.", sourceObjective = "Tötet die Kultisten, die Jaedenar im Teufelswald besetzen.", completion = "Gute Arbeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[76197] = { id = 76197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Einblick des Schreckens", description = "Wir werden gemeinsam auf Euren Befehl zuschlagen, {name}.\n\n<Maiev lässt die Schultern knacken.>\n\nDas Letzte, was dieser Teufel sehen wird, sind unsere Schwerter.", sourceObjective = "Besiegt Kultist Nethus.", progress = "Wir müssen das zu Ende bringen, {name}.", completion = "Unsere Schildwachen... verzerrt und entstellt! Das geht so nicht. Wir werden den Anführer dieses verderbten Einfalls zur Strecke bringen, und ich werde mir seinen Kopf holen!", sourceObjectiveStatus = "unverified-source-field" }
quests[76203] = { id = 76203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schritt in die Schatten", description = "Ihre Reihen wurden ausgedünnt und ihre Leichen gereinigt. Das habt Ihr gut gemacht.\n\n<Maiev verlagert ihr Gewicht und blickt auf den Weg zur Schattenfeste.>\n\nKommt, {name}. Wir müssen finden, was in der Tiefe lauert, und ihm ein Ende bereiten.", sourceObjective = "Durchquert die Schattenfeste mit Maiev Schattensang und kümmert Euch um alle Bedrohungen, die sich Euch in den Weg stellen.", completion = "Wir brauchen das Überraschungsmoment nicht mehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[76205] = { id = 76205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Zünglein an der Waage", description = "Die Zeit für Feinheiten ist vorbei. Lord Hel'nurath hat sich uns offenbart... und ich werde erst ruhen, wenn er tot ist.\n\n<Maiev beißt die Zähne zusammen.>\n\nMacht Euch bereit, {name}. Gemeinsam werden wir diesen Dämonen zeigen, warum sie die Kaldorei fürchten sollten.", sourceObjective = "Tötet Gegner in der Schattenfeste.", completion = "Ich habe ihre Schreie von hier aus gehört, {name}. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[76206] = { id = 76206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Herz des Problems", description = "Unglaublich, wie viel Nari durchgemacht hat. Diese Verdrehung unserer Geschichte, unserer Kultur... meiner Familie.\n\n<Lysander blickt kurz zu seiner Schwester.>\n\nDiese Dämonen sind von irgendwo hierhergekommen. Ich bin sicher, dass die Quelle ihres Einfalls in den Tiefen unseres Grabhügels liegt. Ihr und ich, wir können das beenden.\n\nIch werde nicht zulassen, dass dieser Ort sie länger heimsucht, {name}.", sourceObjective = "Schließt 4 Portale in den Wirbelnden Nether in den Tiefen der Schattenfeste.", completion = "Lysander... Er ist entschlossen, das gebe ich zu.\n\nUnd tapfer.\n\nDanke, {name}. Jetzt... ist es Zeit, den Anführer von all dem hier zu stellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[76207] = { id = 76207, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zorn der Wächter", description = "Lord Hel'nuraths Übermut gab mir eine Gelegenheit, zu beobachten, was er tut. Ich glaube, ich konnte eine Möglichkeit für uns ausmachen, zuzuschlagen.\n\n<Arko'narin blickt kurz zu ihrem Bruder.>\n\nIch fürchte aber, das wird Lysander viel abverlangen. Doch ich weiß, dass er alles geben wird. Vielleicht... vielleicht habe ich das falsch aufgefasst.\n\nEs ist an der Zeit, meine... unsere Dämonen zur Ruhe zu betten.", sourceObjective = "Verteidigt Lysander, während er versucht, Lord Hel'nuraths Ritual zu unterbrechen.", completion = "Macht Euch um mich keine Sorgen, {name}. Meine Schwester tut das schon zur Genüge.\n\nSchaut Euch stattdessen den Mondbrunnen an. Er ist wunderschön...", sourceObjectiveStatus = "unverified-source-field" }
quests[76212] = { id = 76212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Mal für einen Beschützer", description = "Traditionen sollten uns nicht behindern, {name}. Sie sollten die Zukunft mitgestalten.\n\n<Maiev sieht zu Lysander, bevor sie Euch wieder anblickt.>\n\nIch habe auch meiner Wahrnehmung gestattet, mich zu behindern. Doch jetzt nicht mehr. Ich bin es leid, unser Volk gespalten zu sehen, egal, welche Mittel es nutzt, um die Welt oder sich selbst ein wenig besser zu machen.\n\nEs ist Zeit, dass ich Lysander sein Mal verleihe. Die Kaldorei sind den Wandel gewohnt. Unsere Traditionen sollten sich unserem Leben anpassen und es nicht definieren.", sourceObjective = "Seht der Zeremonie zu, wie Lysander seine Gesichtszeichnung erhält.", completion = "Ich glaube es nicht, {name}! Ich kann es nicht glauben!\n\nWie...? Warum...? Ich werde mich ewig an den heutigen Tag erinnern. Habt Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[76213] = { id = 76213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehre der Göttin", description = "Heute wird gefeiert, {name}. Und heute gibt es einen Neuanfang.\n\nArko'narin und Lysander haben mich daran erinnert, dass die Kaldorei den Wandel gewohnt sind. Manchmal vergesse ich, wie lange ich weg war und wie sehr sich mein Volk während meiner Abwesenheit weiterentwickelt hat.\n\n<Maiev schaut hoch in den Himmel.>\n\nLysander feiert diesen Tag, doch Euer Dienst bedarf auch der Anerkennung. Kommt, {name}.", sourceObjective = "Lernt die Bedeutung des Begriffs Ama'shan von Maiev Schattensang.", completion = "Geht mit erhobenem Haupt, Ama'shan {name}.\n\nMögen Eure Taten den Kaldorei weiterhin eine Inspiration sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[76214] = { id = 76214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewegt Euch", description = "Der große Stylecheck bietet uns die Gelegenheit, gut dazustehen, {class}.\n\nDie Kamera sorgt dafür, dass wir immer gut aussehen.\n\nAlso konzentriert Euch auf mich und meine Kamera, folgt meinen Anweisungen und ich rücke Euch ins beste Licht!", sourceObjective = "Konzentriert Euch auf den Fotografen und folgt den Anweisungen.", progress = "Konzentriert Euch auf mich und folgt meinen Anweisungen. \n\nIch rücke Euch ins beste Licht.", completion = "Die Kamera lügt nicht, {name}.\n\nIhr seid ein schicker {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[76217] = { id = 76217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lebende Geschichte", description = "Mein Name ist Nirobin. Den solltet Ihr Euch merken, denn ich bin ein Genie, was arkane Handschriftenkunde angeht! Das ist schon eine wichtige Auszeichnung, wenn ich das mal so sagen darf... Und ich sage das mal so!\n\nIch habe zahllose Stunden damit verbracht, blaue und bronzene Drachenmagie zu verbinden, um die Geschichte zu untersuchen wie nie zuvor. Heute werden Ihr und ich die Früchte meiner Arbeit ernten!\n\nBeginnen wir damit, meine Instrumente auf einen wunderbar erhaltenen Kelch anzuwenden, der auf der Verbotenen Insel entdeckt wurde.", sourceObjective = "Aktiviert Nirobins Instrumente, um den interessanten Dracthyrkelch zu analysieren.", progress = "Ihr seid vielleicht verängstigt.\n\nVersucht, tief in Eurem Inneren nach Stärke zu suchen... denn es gibt nichts, was ich persönlich tun könnte, um Euch dabei zu helfen.", completion = "Unerwartet...\n\nAber \"Unerwartet\" ist genau das, wofür Pioniere wie ich geboren wurden!\n\nImmer weiter! Für die Forschung!", sourceObjectiveStatus = "unverified-source-field" }
quests[76241] = { id = 76241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Laborpartner eines Eichhörnchens", description = "Ich konnte endlich die Geschichte zum Leben erwecken! Ich hatte Erfolg!\n\nJetzt müssen wir Eure ganz besonderen Fähigkeiten einsetzen, um weiterzumachen. Genauer gesagt Eure Fähigkeit, nach draußen zu gehen, ohne vor Angst zu sterben.\n\nIch kanalisiere meine Magie auf unseren neuen Freund hier und teleportiere ihn so an den Ort mit der höchsten Konzentration resonanter Energie, die mit dem Relikt in Verbindung steht. Ihr trefft ihn dort und wartet auf weitere Anweisungen.\n\nKeine Sorge! Ihr werdet meine Magie vielleicht nicht ganz verstehen, aber vertraut darauf, dass mein Intellekt uns beide gut führen wird!", sourceObjective = "Trefft Reese am Verlorenen Athenäum auf der Verbotenen Insel, um Eure Forschung fortzusetzen.", completion = "<Aus dem Mund dieses arkanen Eichhörnchens ertönt knisternd die Stimme von Nirobin.>\n\n{name}? Könnt Ihr mich hören? Hier ist Nirobin! Handschriftenkundiges Genie und leicht agoraphobisch!\n\nIch nehme an, Ihr seid bereit, dieses Tierchen einzusetzen und die verlorenen Geheimnisse der Dracthyrzivilisation zu lüften. Warum würdet Ihr Euch sonst mit einem Eichhörnchen unterhalten?", sourceObjectiveStatus = "unverified-source-field" }
quests[76242] = { id = 76242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Forschungsarbeit für die Ewigkeit", description = "Reese hier hat einen Heißhunger auf Hinweise. Hinweise auf die Vergangenheit!\n\nGenauer gesagt setzen wir meine einzigartige Magie ein, um Energie zu enthüllen und zu analysieren, die mit der gleichen Frequenz schwingt wie unser Relikt.\n\nIhr werdet Reese zu diesen \"Hinweisen\" führen, wo ich ihn dann als Fernknoten einsetze, um diese Energien zu absorbieren.\n\nWenn wir die Energiekapazität unseres Tierchens ausgereizt haben, teleportiere ich es hierher zurück und transmutiere alles in kalte, harte Daten.\n\n<Reese zwinkert Euch zu. Wie seltsam...>", sourceObjective = "Verschlingt Hinweise im Verlorenen Athenäum mit Reese.", progress = "Man möchte meinen, dass ich mich mit der Geschichte der Verbotenen Insel auskenne, schließlich war ich Tausende von Jahren dort.\n\nAber, Überraschung! Ich war damals für die Welt außerhalb meines Labors nicht besonders zu gebrauchen.", completion = "Ich bin völlig verblüfft und ein wenig beeindruckt, dass Ihr keinerlei Anzeichen von Scham gezeigt habt, als Ihr ein fliegendes, durchscheinendes blaues Eichhörnchen eskortiert habt. Bemerkenswert! Bravo!\n\nFürs Erste bitte ich Euch, diese Belohnung anzunehmen. Wenn sie Euch nicht genügt, schreibt an die Akademie und beschwert Euch über meine jährliche Besoldung.\n\nUnd bereitet Euch auf weitere Exkursionen im Namen der Handschriftenkunde und in meinem vor!", sourceObjectiveStatus = "unverified-source-field" }
quests[76244] = { id = 76244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prinz in Gefahr", description = "Ich habe gerade gegen ein Rudel wilder Gnolle gekämpft, die meinen Prinzen bedroht haben, da war da plötzlich ein Lichtblitz! Ich fand mich an diesem seltsamen Ort wieder und mein Prinz war verschwunden! Das muss diese ruchlose Matriarchin Blaupelz gewesen sein!\n\nBitte findet Prinz Wrynn und zeigt es diesen Gnollen!", sourceObjective = "Besiegt zeitverlorene Gnolle und findet den vermissten Llane Wrynn.", completion = "Ich danke Euch. Der Prinz ist wohlbehalten zurückgekehrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[76246] = { id = 76246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manasturms Mysterium", description = "Die Manasturms sind... absolut einzigartig.\n\nIhre Romanze ist explosiv, aber der Funke, der diese Flammen entzündet hat, war recht klein. Ungewöhnlicherweise hat Millhaus mit mangelndem Selbstvertrauen zu kämpfen.\n\nIhr müsst für uns dort hingehen und dabei helfen, sie zusammenzubringen. Mögen die Titanen uns allen beistehen...", sourceObjective = "Sprecht mit Millhaus Manasturm in Dalaran.", progress = "Das Chaos, für das die beiden sorgen werden, beunruhigt mich sehr. Aber die Zeitlinie muss bewahrt werden.", completion = "Ihr habt dafür gesorgt, dass die Ereignisse so bleiben, wie sie sein sollten, und zwei Gnomen geholfen, die Liebe zu finden.\n\nDas ist gut. Wir sollten uns auf die positiven Aspekte konzentrieren. Nicht auf das Chaos, das sie in der Zukunft verbreiten werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[76247] = { id = 76247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Feuer müssen brennen", description = "Die über das Land verteilten Schlüsselflammenkohlenpfannen halten die Dunkelheit fern und schützen unser Volk. Viele sind allerdings erloschen, da die für sie benötigten strahlenden Überbleibsel immer schwerer zu finden sind.\n\nWir haben hart daran gearbeitet, unsere Kohlenpfanne stets am Brennen zu halten, könnten aber gut Eure Hilfe brauchen.\n\nBitte holt Überbleibsel aus unseren Vorräten und stärkt damit die Schlüsselflamme unserer Familie.", sourceObjective = "Sammelt 5 Überrestevorräte des Hügelpinnenhofs und verwendet sie, um die Schlüsselflamme des Hügelpinnenhofs zu stärken.", progress = "Habt Ihr unsere Schlüsselflamme gestärkt?", completion = "Die Wärme der Flamme schürt unsere Hoffnung darauf, diese Lande zurückerobern zu können. Bitte nehmt ein paar dieser überzähligen Überbleibsel und helft, andere Schlüsselflammen in der Umgebung zum Leuchten zu bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[76251] = { id = 76251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flügelbestien", description = "Ich glaube, meine Zeitversetzung wurde von den schrecklichen Kreaturen im Süden ausgelöst.\n\nIch höre sie sogar jetzt noch, ihre monströsen Geräusche. Zweifelsohne haben sie mich aus meiner ursprünglichen Zeitlinie gerissen, um mich zu verhöhnen.\n\nTötet sie für mich und die Sicherheit aller guten Völker dieser Welt.", sourceObjective = "Tötet 10 Flügelbestien in der Winterpelzhöhle im Azurblauen Gebirge.", progress = "Und? Worauf wartet Ihr? Denkt an all die Kinder, die Ihr vor diesen monströsen Kreaturen retten könnt.\n\nNicht, dass ich welche gesehen hätte, aber man kann nie wissen.", completion = "Ihr habt dieser Welt einen Dienst erwiesen.\n\n<Nathanos schaudert.>\n\nNiemand sollte in seinem Leben derartige Kreaturen sehen müssen. Ich höre sie immer noch quaken...", sourceObjectiveStatus = "unverified-source-field" }
quests[76257] = { id = 76257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geißelstein des Dunkelmeisters", description = "<Der Geißelstein in Eurer Hand fühlt sich so echt an wie alles andere in dieser Erinnerung. Er sendet Kälte bis in Euer Mark, während er nur in Eurer Hand liegt.\n\nEr mag ein Relikt der Vergangenheit sein, aber die Argentumdämmerung sollte dennoch von seiner Existenz erfahren.\n\nDas Ritual, das mit Evas Tagebuch durchgeführt wurde, könnte größere Folgen haben, als von Euch beiden angenommen.>", sourceObjective = "Findet jemanden, der Interesse am Geißelstein des Dunkelmeisters hat.", completion = "Ein Geißelstein? Das verstehe ich nicht. Wie habt Ihr den nur gefunden? Nach allem, was wir getan haben, hier und in Nordend...\n\nNein, es spielt keine Rolle. Ich werde ihn nehmen und dafür sorgen, dass er zerstört wird, {name}. Das muss einer der letzten sein, die existieren. Mit Sicherheit.\n\nWenn Ihr noch mehr davon findet, bringt sie auch zu mir. Ich hoffe um unser aller Willen, dass wir zum letzten Mal darüber sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[76258] = { id = 76258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Feuer wird Euch mit der Zeit läutern!", description = "Dieser miese kleine Schlackeelementar hat sich das Herz meiner Schmiede unter den Nagel gerissen! Ohne es ist eine Zeitschmiede nur, na ja, eine Schmiede. Und mit der kann kein Zeitenschmied was anfangen!\n\nSelbst wenn wir Muschelschalemayne hätten, könnte ich es nicht reparieren.\n\nEine solche Macht darf nicht im Besitz dieses... dieses geschmolzenen Trottels bleiben!\n\nDie anderen Elementare haben sich davongemacht in Richtung der Türme. Ich verwette die Hälfte meines Bartes darauf, dass auch der Große nicht weit sein kann.", sourceObjective = "Beschafft das Herz der Zeitschmiede.", progress = "Diese verwünschten Elementare müssen aus dem Herz meiner Schmiede gekommen sein. Wurde es irgendwie destabilisiert?\n\nIn jedem Fall sind das schlechte Nachrichten. Jeder Zeitenschmied, der was auf sich hält, weiß: Temporal- und Elementarenergie sind eine ganz schlechte Mischung.", completion = "<Ironus fasst sich erleichtert an die Brust und lächelt breit.>\n\nDas war ganz schön knapp! Wie hätte es denn ausgesehen, wenn die Grenze des Äons kurz nach meiner Ankunft abbrennt? Wie peinlich das gewesen wäre.\n\nUnd wie's scheint, hat eins der kleinen Elementärchen aus meiner Schmiede Gefallen an Euch gefunden! Behaltet ihn gern.\n\nNein, wirklich, ich bestehe darauf. Behaltet ihn. Ich will ihn nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[76263] = { id = 76263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zitadelle des Schreckens - Naxxramas", description = "Vor langer Zeit hielten magische Schutze über Naxxramas unseren Angriff auf Kel'Thuzads Streitkräfte auf. Ich war damals in der Lage, unsere Armee zu verbergen, damit wir an ihnen vorbeischleichen konnten, aber seitdem habe ich gelernt, wie man Schutze bannt, sollte das einmal nötig sein.\n\nIch muss zugeben, dass ich Eure Geschichte nicht glauben kann. Aber wenn Ihr Eure Nachforschungen so sehr fortsetzen wollt, kann ich Euer Insigne verzaubern, damit Ihr diese Barrieren selbst durchbrechen könnt. Es wird Euch allerdings etwas kosten.", sourceObjective = "Erzmagierin Angela Dosantos in den Östlichen Pestländern will 5 Arkankristalle, 6 große glänzende Splitter, 1 rechtschaffene Kugel und 60 Goldstücke. Ihr müsst außerdem einen wohlwollenden Ruf bei der Argentumdämmerung haben.", progress = "Habt Ihr die nötigen Reagenzien mitgebracht?", completion = "Ihr werdet ein leichtes Kitzeln spüren, {name}. Dieses Gefühl bedeutet, dass es funktioniert. Sobald der Zauber abgeschlossen ist, solltet Ihr sehen können, was Ihr zu finden glaubt.", sourceObjectiveStatus = "unverified-source-field" }
quests[76264] = { id = 76264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zitadelle des Schreckens - Naxxramas", description = "Vor langer Zeit hielten magische Schutze über Naxxramas unseren Angriff auf Kel'Thuzads Streitkräfte auf. Ich war damals in der Lage, unsere Armee zu verbergen, damit wir an ihnen vorbeischleichen konnten, aber seitdem habe ich gelernt, wie man Schutze bannt, sollte das einmal nötig sein.\n\nIch muss zugeben, dass ich Eure Geschichte nicht glauben kann. Aber wenn Ihr Eure Nachforschungen so sehr fortsetzen wollt, kann ich Euer Insigne verzaubern, damit Ihr diese Barrieren selbst durchbrechen könnt. Gegen eine kleine Gebühr.", sourceObjective = "Erzmagierin Angela Dosantos in den Östlichen Pestländern will 2 Arkankristalle, 3 große glänzende Splitter und 30 Goldstücke. Ihr müsst außerdem einen respektvollen Ruf bei der Argentumdämmerung haben.", progress = "Habt Ihr die nötigen Reagenzien mitgebracht?", completion = "Ihr werdet ein leichtes Kitzeln spüren, {name}. Dieses Gefühl bedeutet, dass es funktioniert. Sobald der Zauber abgeschlossen ist, solltet Ihr sehen können, was Ihr zu finden glaubt.", sourceObjectiveStatus = "unverified-source-field" }
quests[76265] = { id = 76265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zitadelle des Schreckens - Naxxramas", description = "Vor langer Zeit hielten magische Schutze über Naxxramas unseren Angriff auf Kel'Thuzads Streitkräfte auf. Ich war damals in der Lage, unsere Armee zu verbergen, damit wir an ihnen vorbeischleichen konnten, aber seitdem habe ich gelernt, wie man Schutze bannt, sollte das einmal nötig sein.\n\nIch muss zugeben, dass ich Eure Geschichte nicht glauben kann. Aber wenn Ihr Eure Nachforschungen so sehr fortsetzen wollt, kann ich Euer Insigne verzaubern, damit Ihr diese Barrieren selbst durchbrechen könnt.", sourceObjective = "Erzmagierin Angela Dosantos in den Östlichen Pestländern wird Eure Anstecknadel der Argentumdämmerung kostenlos ermächtigen. Ihr müsst einen ehrfürchtigen Ruf bei der Argentumdämmerung haben.", completion = "Ihr werdet ein leichtes Kitzeln spüren, {name}. Dieses Gefühl bedeutet, dass es funktioniert. Sobald der Zauber abgeschlossen ist, solltet Ihr sehen können, was Ihr zu finden glaubt.", sourceObjectiveStatus = "unverified-source-field" }
quests[76266] = { id = 76266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Menge Aufgaben", description = "Hallo, {name}! Ich habe heute einen unglaublich aufregenden Auftrag. Ihr müsst für mich sieben Brotlaibe in Sturmwind und fünf Milchkrüge in Orgrimmar verteilen. Danach runden wir das ab mit...\n\n<Chromie schaut auf eine Notiz in ihrer Hand.>\n\nSiebenhundertundzweiundvierzig Reiskörnern, die wir in ganz Pandaria verteilen!", sourceObjective = "Erledigt eine Reihe von Aufgaben im Gasthaus am Irgendwo an der Grenze des Äons.", completion = "Wow, das war unglaublich! Die dreitägige Reise mit dem Kaiser von Pandaria und seiner Gruppe von Helden war wirklich der Höhepunkt.\n\nVielen Dank, dass Ihr mir erlaubt habt, die Flügel auszustrecken, {name}. Ich übernehme ab hier.", sourceObjectiveStatus = "unverified-source-field" }
quests[76268] = { id = 76268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geißelsteine des Verderbers", progress = "Ein Geißelstein des Verderbers war das Insigne der Oberanführer der Geißel. Mächtige Wesen, die einst eine hohe Position in der Geißel bekleideten, besaßen stets einen.\n\nIch habe früher Ehrenmarken dagegen eingetauscht. Ich bezweifle zwar, dass Ihr je wieder welche findet, aber wenn doch, bringt diese bitte sofort zu mir, damit ich sie vernichten lassen kann.", completion = "Jeden Tag tauchen weitere Geißelsteine auf, {name}, von Euch und immer mehr anderen Abenteurern.\n\nZum Glück sind keine unserer Soldaten unerklärlicherweise verschwunden, und ich habe auch nicht mehr markerschütternde Schreie gehört, als für diese Gegend normal ist.\n\nIch würde an Eurer Stelle lieber nicht fragen. Hier ist Eure Belohnung." }
quests[76269] = { id = 76269, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein fehlplatziertes Ei", description = "Oh je, das ist eine knifflige Aufgabe. Ihr müsst ein Ei an einen Ort bringen, an dem Rhonin es mit Sicherheit bemerken wird. Das mag seltsam klingen, aber, dass er das Ei entdeckt, setzt die Ereignisse in Gang, die Alexstrasza von der alten Horde befreien und auch das Ei retten werden!\n\nWir schicken euch nach Dun Algaz. Das ist nicht der Ort, an dem das alles stattfinden sollte, aber die Zeit ist im Moment wie Käse. Lecker und voller Löcher.\n\nOh, und hier ist etwas Sand. Damit könnt Ihr Euch etwas besser tarnen.", sourceObjective = "Findet das Rotdrachenei und platziert es an einem auffälligen Ort.", progress = "Habt Ihr einen guten Ort für das Ei gefunden?", completion = "Habt Ihr es an der richtigen Stelle abgelegt? Aber ja, natürlich, sonst wären wir ja nicht hier!\n\nAls Alexstrasza befreit wurde, gelang ihr der Sieg bei der Schlacht von Grim Batol. Was aber noch wichtiger ist: Sie und die anderen Aspekte zwangen Todesschwinge zu einem überstürzten Rückzug. Wer weiß, was Todesschwinge erreicht hätte, wenn Rhonin sie nicht gefunden hätte?\n\n<Chromie senkt ihre Stimme und blickt Alexstrasza an.>\n\nSie traf ein, kurz nachdem Ihr gegangen wart. Als ob sie wüsste, was wir vorhatten!", sourceObjectiveStatus = "unverified-source-field" }
quests[76270] = { id = 76270, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geißelsteine des Eindringlings", progress = "Ein Geißelstein des Eindringlings war das Insigne der Elitetruppen der Geißel. Man fand sie manchmal bei den stärkeren Kämpfern der Truppen, die in Stratholme und Scholomance stationiert waren.\n\nIch habe früher Ehrenmarken dagegen eingetauscht. Ich bezweifle zwar, dass Ihr je wieder welche findet, aber wenn doch, bringt diese bitte sofort zu mir, damit ich sie vernichten lassen kann.", completion = "Jeden Tag tauchen weitere Geißelsteine auf, {name}, von Euch und immer mehr anderen Abenteurern.\n\nZum Glück sind keine unserer Soldaten unerklärlicherweise verschwunden, und ich habe auch nicht mehr markerschütternde Schreie gehört, als für diese Gegend normal ist.\n\nIch würde an Eurer Stelle lieber nicht fragen. Hier ist Eure Belohnung." }
quests[76271] = { id = 76271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewegt Euch", description = "Der große Stylecheck bietet uns die Gelegenheit, gut dazustehen, {class}.\n\nDie Kamera sorgt dafür, dass wir immer gut aussehen.\n\nAlso konzentriert Euch auf mich und meine Kamera, folgt meinen Anweisungen und ich rücke Euch ins beste Licht!", sourceObjective = "Konzentriert Euch auf den Fotografen und folgt den Anweisungen.", progress = "Konzentriert Euch auf mich und folgt meinen Anweisungen. \n\nIch rücke Euch ins beste Licht.", completion = "Die Kamera lügt nicht, {name}.\n\nIhr seid ein schicker {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[76272] = { id = 76272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewegt Euch", description = "Der große Stylecheck bietet uns die Gelegenheit, gut dazustehen, {class}.\n\nDie Kamera sorgt dafür, dass wir immer gut aussehen.\n\nAlso konzentriert Euch auf mich und meine Kamera, folgt meinen Anweisungen und ich rücke Euch ins beste Licht!", sourceObjective = "Konzentriert Euch auf den Fotografen und folgt den Anweisungen.", progress = "Konzentriert Euch auf mich und folgt meinen Anweisungen. \n\nIch rücke Euch ins beste Licht.", completion = "Die Kamera lügt nicht, {name}.\n\nIhr seid ein schicker {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[76273] = { id = 76273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewegt Euch", description = "Der große Stylecheck bietet uns die Gelegenheit, gut dazustehen, {class}.\n\nDie Kamera sorgt dafür, dass wir immer gut aussehen.\n\nAlso konzentriert Euch auf mich und meine Kamera, folgt meinen Anweisungen und ich rücke Euch ins beste Licht!", sourceObjective = "Konzentriert Euch auf den Fotografen und folgt den Anweisungen.", progress = "Konzentriert Euch auf mich und folgt meinen Anweisungen. \n\nIch rücke Euch ins beste Licht.", completion = "Die Kamera lügt nicht, {name}.\n\nIhr seid ein schicker {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[76274] = { id = 76274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewegt Euch", description = "Der große Stylecheck bietet uns die Gelegenheit, gut dazustehen, {class}.\n\nDie Kamera sorgt dafür, dass wir immer gut aussehen.\n\nAlso konzentriert Euch auf mich und meine Kamera, folgt meinen Anweisungen und ich rücke Euch ins beste Licht!", sourceObjective = "Konzentriert Euch auf den Fotografen und folgt den Anweisungen.", progress = "Konzentriert Euch auf mich und folgt meinen Anweisungen. \n\nIch rücke Euch ins beste Licht.", completion = "Die Kamera lügt nicht, {name}.\n\nIhr seid ein schicker {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[76275] = { id = 76275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewegt Euch", description = "Der große Stylecheck bietet uns die Gelegenheit, gut dazustehen, {class}.\n\nDie Kamera sorgt dafür, dass wir immer gut aussehen.\n\nAlso konzentriert Euch auf mich und meine Kamera, folgt meinen Anweisungen und ich rücke Euch ins beste Licht!", sourceObjective = "Konzentriert Euch auf den Fotografen und folgt den Anweisungen.", progress = "Konzentriert Euch auf mich und folgt meinen Anweisungen. \n\nIch rücke Euch ins beste Licht.", completion = "Die Kamera lügt nicht, {name}.\n\nIhr seid ein schicker {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[76276] = { id = 76276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein verwandeltes Land", description = "Die Ankunft von Amirdrassil bringt große Veränderungen nach Azeroth. Seine Wurzeln finden eine Heimat in der Erde und seine Äste greifen nach dem Himmel, um die Luft zu fühlen.\n\nDas ist ein verheißungsvoller Moment, aber wir dürfen nicht unsere Verbündeten überall auf den Inseln vergessen. Besucht unsere Nachbarn und überprüft, ob sie sicher sind.", sourceObjective = "Seht nach Bewohnern der Dracheninseln in der Nähe.", progress = "Amirdrassil ist sicher angekommen, aber auch unsere Verbündeten müssen in Sicherheit sein.", completion = "Es beruhigt mich, dass es unseren Freunden gut geht. Habt Dank, dass Ihr sie aufgesucht habt, Champion.", sourceObjectiveStatus = "unverified-source-field" }
quests[76278] = { id = 76278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewegt Euch", description = "Der große Stylecheck bietet uns die Gelegenheit, gut dazustehen, {class}.\n\nDie Kamera sorgt dafür, dass wir immer gut aussehen.\n\nAlso konzentriert Euch auf mich und meine Kamera, folgt meinen Anweisungen und ich rücke Euch ins beste Licht!", sourceObjective = "Konzentriert Euch auf den Fotografen und folgt den Anweisungen.", progress = "Konzentriert Euch auf mich und folgt meinen Anweisungen. \n\nIch rücke Euch ins beste Licht.", completion = "Die Kamera lügt nicht, {name}.\n\nIhr seid ein schicker {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[76280] = { id = 76280, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neumond", description = "Mit diesen Opfergaben und dem Wasser des Brunnens der Ewigkeit, haben wir alles, was wir brauchen.\n\nSprecht mit mir, wenn Ihr bereit seid, das Ritual zu beginnen.", sourceObjective = "Sprecht mit Tyrande Wisperwind im Zentrallager, um das Ritual zu beginnen.", completion = "Amirdrassil... endlich. Es fühlt sich an, als hätte ich nicht gemerkt, dass ich die Luft angehalten habe, und jetzt ausgeatmet. {name}, ich kann Euch nicht genug für Eure Hilfe danken.", sourceObjectiveStatus = "unverified-source-field" }
quests[76281] = { id = 76281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grund zu Feiern", description = "Endlich... Nun lasst uns feiern, was wir alles überwunden haben, und die Hoffnung umarmen, die so hell unter den versammelten Kaldorei erstrahlt.\n\nKommt, schließt Euch den Festlichkeiten an.", sourceObjective = "Bedient Tische beim Fest in Bel'ameth.", completion = "So viel Leben und Freude verweilt hier unter diesen Ästen. Möge es immer so sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[76282] = { id = 76282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein beunruhigendes Gefühl", description = "Ah, {name}! Genau Euch habe ich gesucht. Ich mache mir ein wenig Sorgen um Khadgar. Es ist sicher nichts Ernstes, aber er scheint sich nicht so zu amüsieren wie alle anderen. Er wirkt irgendwie... abgelenkt.\n\nIch will meine Nase nicht in fremde Angelegenheiten stecken, aber würdet Ihr ihm ein Getränk für mich bringen? Vielleicht öffnet er sich für Euch.", sourceObjective = "Bringt Khadgar in Bel'ameth ein Getränk.", progress = "Konntet Ihr Khadgar aufmuntern, {name}?", completion = "Habt Dank. Ich wusste, dass er mit Euch sprechen würde.\n\nVielleicht können wir uns beide nun entspannen.", sourceObjectiveStatus = "unverified-source-field" }
quests[76283] = { id = 76283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Andu-falah-dor", description = "Meine Mutter hat uns gebeten, sie beim Mondbrunnen zu treffen.\n\nEs ist spät, wir sollten sie nicht länger warten lassen.\n\nTrefft mich dort.", sourceObjective = "Sprecht mit Merithra in Bel'ameth.", completion = "Während Amirdrassil über die Grenzen des Traums hinaus in Azeroth erblüht, nimmt meine Schwester den Platz eines neuen Aspekts ein.\n\n<Alexstrasza wirft einen Blick zum Portal und lächelt.>\n\nUnd Ihr, {name}, habt all diese Ereignisse zu einem glücklichen Abschluss gebracht.", sourceObjectiveStatus = "unverified-source-field" }
quests[76284] = { id = 76284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewegt Euch", description = "Der große Stylecheck bietet uns die Gelegenheit, gut dazustehen, {class}.\n\nDie Kamera sorgt dafür, dass wir immer gut aussehen.\n\nAlso konzentriert Euch auf mich und meine Kamera, folgt meinen Anweisungen und ich rücke Euch ins beste Licht!", sourceObjective = "Konzentriert Euch auf den Fotografen und folgt den Anweisungen.", completion = "Die Kamera lügt nicht, {name}.\n\nIhr seid eine schicke {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[76285] = { id = 76285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewegt Euch", description = "Der große Stylecheck bietet uns die Gelegenheit, gut dazustehen, {class}.\n\nDie Kamera sorgt dafür, dass wir immer gut aussehen.\n\nAlso konzentriert Euch auf mich und meine Kamera, folgt meinen Anweisungen und ich rücke Euch ins beste Licht!", sourceObjective = "Konzentriert Euch auf den Fotografen und folgt den Anweisungen.", progress = "Konzentriert Euch auf mich und folgt meinen Anweisungen. \n\nIch rücke Euch ins beste Licht.", completion = "Die Kamera lügt nicht, {name}.\n\nIhr seid ein schicker {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[76286] = { id = 76286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewegt Euch", description = "Der große Stylecheck bietet uns die Gelegenheit, gut dazustehen, {class}.\n\nDie Kamera sorgt dafür, dass wir immer gut aussehen.\n\nAlso konzentriert Euch auf mich und meine Kamera, folgt meinen Anweisungen und ich rücke Euch ins beste Licht!", sourceObjective = "Konzentriert Euch auf den Fotografen und folgt den Anweisungen.", progress = "Konzentriert Euch auf mich und folgt meinen Anweisungen. \n\nIch rücke Euch ins beste Licht.", completion = "Die Kamera lügt nicht, {name}.\n\nIhr seid ein schicker {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[76287] = { id = 76287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewegt Euch", description = "Der große Stylecheck bietet uns die Gelegenheit, gut dazustehen, {class}.\n\nDie Kamera sorgt dafür, dass wir immer gut aussehen.\n\nAlso konzentriert Euch auf mich und meine Kamera, folgt meinen Anweisungen und ich rücke Euch ins beste Licht!", sourceObjective = "Konzentriert Euch auf den Fotografen und folgt den Anweisungen.", progress = "Konzentriert Euch auf mich und folgt meinen Anweisungen. \n\nIch rücke Euch ins beste Licht.", completion = "Die Kamera lügt nicht, {name}.\n\nIhr seid ein schicker {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[76288] = { id = 76288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewegt Euch", description = "Der große Stylecheck bietet uns die Gelegenheit, gut dazustehen, {class}.\n\nDie Kamera sorgt dafür, dass wir immer gut aussehen.\n\nAlso konzentriert Euch auf mich und meine Kamera, folgt meinen Anweisungen und ich rücke Euch ins beste Licht!", sourceObjective = "Konzentriert Euch auf den Fotografen und folgt den Anweisungen.", completion = "Die Kamera lügt nicht, {name}.\n\nIhr seid ein schicker {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[76290] = { id = 76290, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Omarions zweiter Leitfaden", description = "Wilhelm,\n\nwenn Ihr das lest, ist der erste Abenteurer, den ich zu Euch schickte, gefallen. So wie auch ich letztes Endes. Ich will, dass Ihr wisst, dass meine letzten Gedanken Euch und Eurer Unfähigkeit galten, was Handwerksfertigkeiten angeht.\n\nWas das Buch angeht: Das sind meine übrigen Pläne und Muster. Bitte teilt sie mit jemandem, der fähiger ist. Jedoch bin ich sicher, dass Ihr sie für Euch behalten und Eure Dienste für Unsummen verkaufen werdet, weil Ihr ja schließlich ein Mistkerl seid.\n\nIn Verachtung,\nOmarion", sourceObjective = "Bringt den Leitfaden zu Meisterhandwerker Omarion an der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", completion = "Ah. Mein Buch mit Plänen und Mustern, nur ohne all die Pläne und Muster.\n\n<Omarion öffnet das Buch, schlägt die einzige Seite auf und schließt es sofort wieder.>\n\nIch hoffe, Ihr wollt lernen, wie man Umhänge bestickt.", sourceObjectiveStatus = "unverified-source-field" }
quests[76308] = { id = 76308, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große Stylecheck", description = "Also, das ist auf jeden Fall eine... interessante Aufmachung, {class}.\n\nIch? Voreingenommen? Keinesfalls. Aber ich würde gerne wissen, was die anderen davon halten.\n\nIhr solltet mit dem Transmogrifizierer dort drüben reden und am großen Stylecheck teilnehmen.\n\nDann erfahren wir, wie die öffentliche Meinung zu Eurer Kleidungswahl steht.", sourceObjective = "Sprecht mit einem Transmogrifizierer, um am großen Stylecheck teilzunehmen und ihn abzuschließen.", progress = "Puh, ist mir langweilig.\n\nHabt Ihr den großen Stylecheck schon abgeschlossen?", completion = "Gar nicht mal so übel.\n\nGar nicht mal.\n\nUnd jetzt ab mit Euch. Ich bin es leid, Euch zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[76309] = { id = 76309, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gilneasgambit", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[76310] = { id = 76310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gilneasgambit - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[76311] = { id = 76311, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gilneasgambit - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[76317] = { id = 76317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Traumes", description = "Ein großartiger Baum gedeiht im Traum. Bald wird er nach Azeroth übertreten.\n\nDoch davor müssen wir ihn vor Fyrakks Truppen beschützen. Wir müssen uns vereinen und ihm zu seiner blühenden Geburt verhelfen.\n\nSchließt Euch mir und den anderen im Uralten Zweig an. Wir werden gemeinsam in den Smaragdgrünen Traum reisen.", sourceObjective = "Trefft Euch mit Merithra im Uralten Zweig in den Ebenen von Ohn'ahra.", progress = "Wir müssen Fyrakk aufhalten.", completion = "Vor nicht allzu langer Zeit wurde der Weltenbaum im Smaragdgrünen Traum gepflanzt. Dort ist er sicher.\n\nNun haben unsere Feinde ihren eigenen Weg in den Traum gefunden. Wir müssen unsere Kräfte vereinen und ihn schützen. Der Baum hat so viel Hoffnung... und Potenzial.", sourceObjectiveStatus = "unverified-source-field" }
quests[76318] = { id = 76318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smaragdgrünes Willkommen", description = "Wir haben den Baum geschützt und bewachen alle Eingänge zum Smaragdgrünen Traum. Nun hat Fyrakk Verbündete gefunden, die einen neuen Weg für ihn öffnen können.\n\nIch will dasselbe für Euch und Eure Verbündeten tun. Der grüne Drachenschwarm kann das nicht allein schaffen.\n\nDurch dieses Portal werden wir den Traum gemeinsam betreten. Wir müssen das Reich und alles, was darin gedeiht, schützen.", sourceObjective = "Betretet den Smaragdgrünen Traum durch das Portal im Uralten Zweig.", progress = "Es gibt viel zu tun.", completion = "Fyrakks Macht bedroht das Gefüge des Traums. Wir müssen uns beeilen, diese Welt zu retten. Dieser Drache wird Euch helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[76319] = { id = 76319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuriges Festmahl", description = "Fyrakk beschädigt bereits das Gefüge des Traums. Ich kann es brennen spüren, als ob die Flammen meine Schuppen verzehren würden.\n\nUnd ich weiß, dass diese schwelende Pein nur ein Bruchteil dessen ist, was mein Sohn erleiden musste, als Fyrakk ihn quälte.\n\nAber wir haben eine mächtige Waffe gegen dieses Feuer. Unsere Feendrachen und Drachen verschlingen, was hier nicht hingehört. Sie sind ausgezeichnete Verbündete, wenn sie auch ein wenig schwer zu kontrollieren sind.\n\nJetzt brauchen sie unsere Hilfe. Nehmt das. Reinigt den Himmel von der eindringenden Flamme.", sourceObjective = "Reitet Euren Drachen oder einen Feendrachen, um brennende Stellen im Traum zu verschlingen.", completion = "Fyrakk könnte den Baum jederzeit angreifen. Wir werden die Hilfe der anderen wilden Götter brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[76320] = { id = 76320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wilde Götter unter uns", description = "Der Smaragdgrüne Traum ist die Heimat der wilden Götter der Natur. Wir werden ihre Kraft und ihre Mächte brauchen, um gegen den Schaden anzukämpfen, den Fyrakk diesem Reich zufügt.\n\nDer erste von ihnen ist Goldrinn. Der uralte Wolf hat eine Vorliebe für Azeroth und Sterbliche, also wird er uns sicher helfen.\n\nDie anderen brauchen vielleicht etwas mehr Überzeugungsarbeit.\n\nTrefft mich in der Nähe der Felder der Tagträume, wo die Dryaden und Hüter verweilen.", sourceObjective = "Sucht die wilden Götter und Verbündeten im Smaragdgrünen Traum auf.", completion = "Wir kommen zu spät. Fyrakks Truppen haben ihren Angriff auf den Traum bereits begonnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[76321] = { id = 76321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sengender Ansturm", description = "Die Druiden der Flamme öffnen einen Weg in den Traum für Fyrakks Truppen. Jeden Augenblick kommen mehr von ihnen.\n\nWir müssen diese Flut aufhalten, bevor sie uns überschwemmt.", sourceObjective = "Tötet Primalisten, Djaradin und Druiden der Flamme.", progress = "Fyrakks Truppen müssen ausgemerzt werden, bevor sie im Traum Fuß fassen können.", completion = "Ihr habt gut gekämpft, doch ich fürchte, wir können diese Truppen nicht mehr aufhalten. Sie könnten den Traum für immer verändern.", sourceObjectiveStatus = "unverified-source-field" }
quests[76322] = { id = 76322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Gesicht unserer Feinde", description = "Mächtige Gegner lauern unter den Feinden, die Fyrakk im Traum beschworen hat.\n\nIch habe Cassaphine nicht mehr gesehen, seit sie aus den Hügeln hervorgetreten ist.\n\nFindet sie und helft unseren Verbündeten, die Anführer niederzustrecken.", sourceObjective = "Besiegt Fyrakks mächtige Leutnants und sichert das Schlachtfeld.", progress = "Es schmerzt mich, die Kinder des Traums so verdorben zu sehen.", completion = "Es ist schlimmer, als ich dachte. Jedes Mal, wenn wir ein Portal schließen, öffnen die Druiden der Flamme weitere.\n\nIch fürchte, uns stehen noch größere Gefahren bevor.", sourceObjectiveStatus = "unverified-source-field" }
quests[76323] = { id = 76323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amirdrassil", description = "Dieser Baum ist friedlich im Traum herangewachsen, seit er hier gepflanzt wurde. Wir haben über ihn gewacht und ihn gepflegt.\n\nUnd jetzt, kurz bevor er seine Kinderstube in diesem Reich verlassen und nach Azeroth übertreten will, sehen unsere Feinde ihn als Mittel für ihre eigenen Zwecke.\n\nDoch er ist so viel mehr.\n\nKommt, lasst uns zu Amirdrassil gehen.", sourceObjective = "Trefft Merithra am Fuß von Amirdrassil.", completion = "Wir sind gerade rechtzeitig angekommen. Wir müssen Cassaphine aufhalten, bevor sie dem Baum schaden kann... oder uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[76324] = { id = 76324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ans Feuer verloren", description = "Die Druiden der Flamme stellen eine größere Bedrohung dar, als mir bewusst war. Sie lassen nicht nur zu, dass Fyrakk und seine Truppen in den Traum strömen, sie verführen auch die Bewohner des Traums zur Flamme!\n\nWir dürfen nicht lange darüber grübeln, wie das passieren konnte. Es schmerzt mich, aber die Älteste Cassaphine muss aufgehalten werden.\n\nFolgt Tyrande und... setzt der Dryade ein Ende.", sourceObjective = "Besiegt die Älteste Cassaphine am Fuß von Amirdrassil.", completion = "Der Smaragdgrüne Traum ist ein Ort der wilden Natur, Magie und des Lebens.\n\nEs macht mich traurig, eine der Unseren so enden zu sehen. Ich hoffe, dass sie nicht nur die erste von vielen ist.\n\nWartet... hört Ihr das?", sourceObjectiveStatus = "unverified-source-field" }
quests[76325] = { id = 76325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Fyrakk in die Ecke gedrängt", description = "Ich höre nahende Flügelschläge und rieche die Schattenflamme.\n\nFyrakk ist hier.\n\n<Merithras Zorn ist still, aber lodernd.>\n\nGerithus' Schmerz wird nicht ungesühnt bleiben.", sourceObjective = "Sprecht mit Merithra und bereitet Euch auf Fyrakks Angriff vor.", progress = "Wir müssen zusammenhalten.", completion = "Er hat den Baum verschont?\n\nHat er ein anderes Ziel?\n\nUnd warum hört er auf diesen Druiden der Flamme?", sourceObjectiveStatus = "unverified-source-field" }
quests[76326] = { id = 76326, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu Hause im Traum", description = "Fyrakk hat sich von Amirdrassil zurückgezogen, aber das macht mir nur noch größere Sorgen. Er muss ein anderes Ziel im Traum haben.\n\nWir müssen uns mit den anderen am Fuß des Weltenbaumes beraten. Tyrande und die Kaldorei haben ein Lager errichtet.\n\nIch muss mit Alexstrasza darüber sprechen, wie es weiter geht.", sourceObjective = "Trefft Merithra im Zentrallager unter Amirdrassil.", completion = "Jetzt, wo wir einen Moment zum Durchatmen haben, können wir uns überlegen, was wir als Nächstes tun.\n\nUnd ich weiß, dass wir mit Euch an unserer Seite stärker sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[76327] = { id = 76327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auge von Ysera", description = "Galenoris Bericht ist besorgniserregend.\n\nDer Tempel des Auges ist mein Sitz der Macht hier im Traum. Vor dort aus trete ich mit den Energien des Auges in Kontakt und überwache die Gesundheit des Traums und seiner Bewohner. Die Macht des Auges fließt durch den gesamten Traum und unterstützt Amirdrassils Wachstum.\n\nWenn die Djaradin die Kontrolle darüber übernehmen, könnten sie seine Natur verderben und das Wachstum des Baums stoppen.\n\nMeine Tochter weiß, wie wichtig das Auge ist. Ich werde ihr folgen. Und Ihr solltet es ebenfalls.", sourceObjective = "Reist durch das Portal von Amirdrassil zum Auge von Ysera.", completion = "Das ist also Igiras neuer General? Ich bin nicht beeindruckt. Wir werden über dieses Monster obsiegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[76328] = { id = 76328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neuer Schläger", description = "Galok ist nur ein weiterer von Fyrakks Dienern. Ich lasse mich nicht von seinem Geprahle beeindrucken.\n\nDie Feuerkugel muss sein Wirken sein. Ihre Magie droht, das Auge zu überwältigen. Ysera kanalisiert einen Schild vom Inneren des Tempels aus, aber er scheint nicht so effektiv zu sein wie erhofft.\n\nIch muss Galok stellen. Nutzt meine Magie, um unsere Zauberwirker zu stärken, falls sie geschwächt werden. Die Verteidigung darf nicht fallen!", sourceObjective = "Wendet die Essenz der Träumerin auf 5 Smaragdbewahrer an. Trefft anschließend Ysera im Inneren des Tempels im Auge von Ysera.", progress = "Schnell, {name}! Unsere Verteidiger haben Schmerzen.", completion = "Mutter kämpft...", sourceObjectiveStatus = "unverified-source-field" }
quests[76329] = { id = 76329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdeckter Ermittler", description = "Bodwin berichtet, dass Galok nicht die einzige neue Bedrohung für das Auge darstellt. Die Djaradintruppen darunter werden von zwei anderen angeführt - einer Kriegerin und einer Magierin.\n\nEs wäre unklug, sie direkt in ihrer gut gesicherten Basis anzugreifen. Aber ich bin sicher, dass sie Teil von Galoks Angriffsplan sind.\n\nBitte beschafft mehr Informationen zu diesen Djaradinanführern. Wir müssen wissen, wie wir ihren Angriffen am besten etwas entgegensetzen. Bodwin kann Euch Verstohlenheit verleihen, damit Ihr Euch unentdeckt im Lager umsehen könnt.", sourceObjective = "Spioniert die Djaradinanführer in der Schlackenschlagfestung aus.", completion = "<Merithra ist sehr still. Nur in ihren Augen ist ihr rasender Zorn zu erkennen.>\n\nWir werden Unsersgleichen rächen.", sourceObjectiveStatus = "unverified-source-field" }
quests[76330] = { id = 76330, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entwaffnungsspezialist", sourceObjective = "Tötet 6 Durchdringungsformer und zerstört 8 überwachsene Vorräte.", completion = "Das wird ihre Truppen erheblich schwächen.", sourceObjectiveStatus = "unverified-source-field" }
quests[76331] = { id = 76331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Merithras Gambit", description = "Wir sind so bereit wie nur möglich. Unser Schutz ist in Position, unsere Falle ist bereit zuzuschnappen.\n\nDie Magie der Smaragdbewahrer ist mit Yseras verbunden. Auf Euer Signal werden sie gleichzeitig die magische Verteidigung fallen lassen. Genau darauf wartet Galok. Seine Truppen werden wie aasfressende Vögel hereinströmen.\n\nWir warten auf Euren Befehl, {name}.", sourceObjective = "Befehlt Ysera, die magische Verteidigung fallen zu lassen.", progress = "Auf geht's.", completion = "Ich muss ihr vertrauen. Und mir selbst. Es ist Zeit, zu kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[76332] = { id = 76332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wurzeln schlagen", description = "Unsere Falle hat viele Ebenen.\n\nPflanzt diese Samen in der Stadt. Unsere Gärtner haben den Boden schon vorbereitet. Diese Pflanzen werden effektive Mittel sein, um unsere Feinde zu vergiften. Geht vorsichtig damit um, sie könnten jederzeit aufkeimen.\n\nKiya Federtatze, unsere Umbraklauenhüterin, hatte außerdem eine Idee, wie wir sehr starke Kreaturen festsetzen können. Sprecht mit ihr.\n\nUnd zuletzt trefft Euch mit Somnikus, um allen das Signal zu geben, dass ein Kampf kurz bevor steht.", sourceObjective = "Pflanzt Samen in 8 gepflügte Erdreiche und sprecht mit Kiya Federtatze. Sprecht anschließend mit Somnikus.", progress = "Unsere Falle wird funktionieren, ich bin mir sicher.\n\nSchnell, {name}. Sogar mit der vereinten Kraft von mir und meiner Mutter... Es ist, als würde ein Teil von ihr ihre Einstimmung verhindern. Ich will nicht darüber nachdenken.", completion = "Jetzt... sind wir bereit.", sourceObjectiveStatus = "unverified-source-field" }
quests[76333] = { id = 76333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefahr hoch drei", description = "Galok ist hier. Also läuft alles nach Plan. \n\nWir werden ihm und allen seinen Leutnants ein Ende bereiten.", sourceObjective = "Tötet Galok Schwingenschlitzer und seine Djaradinleutnants Amboss und Schmelzbinderin.", progress = "Wir haben vielleicht die Oberhand, aber wir sollten keinen von ihnen unterschätzen.", completion = "Wir haben Galok beinahe bezwungen. Haltet den Druck aufrecht!", sourceObjectiveStatus = "unverified-source-field" }
quests[76334] = { id = 76334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guter Rat", description = "Galok ist ein Feigling. Er verweigert den direkten Kampf, solange er nicht sicher sein kann, dass er gewinnt.\n\nWir verfügen über nicht genug Ressourcen, um seine Basis anzugreifen. Aber auch wenn wir nicht zu ihm vordringen können, so gibt es vielleicht noch die Möglichkeit, ihn auf unserem eigenen Gebiet in eine Schlacht zu verwickeln.\n\nIch bin zuversichtlich, dass wir für Galok und seine Truppen hier eine Falle ausarbeiten können. Mein Plan ist nicht ohne Risiko und die Kontrolle über das Schlachtfeld wird unser Hauptvorteil sein.\n\nDie Frage ist bloß... Wie locken wir sie her?", sourceObjective = "Besprecht Merithras Plan mit dem grünen Drachenschwarm.", progress = "Ich muss alle Perspektiven hören, besonders bei einem so großen Manöver.", completion = "<Merithra nickt unseren Verbündeten feierlich zu.>\n\nSomit ist es entschieden. Lasst uns mit den Vorbereitungen beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[76335] = { id = 76335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht der Waldes", description = "Nutzt die Fallen, die Ihr ausgelegt habt, zu Eurem Vorteil, {name}. Bezwingt jedes Monster, das es wagt, uns zu drohen!", sourceObjective = "Eliminiert die Djaradinbedrohung im Auge von Ysera. Aktiviert Fallen, um Euch im Kampf zu unterstützen.", progress = "Wir müssen den Traum beschützen!", completion = "Das Blatt wendet sich! Nutzt den Vorteil.", sourceObjectiveStatus = "unverified-source-field" }
quests[76336] = { id = 76336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fliegen und kämpfen", description = "Wir haben den Boden unter unseren Füßen gesichert... nun zu den Lüften.\n\nGalok ist entflogen, doch er ist geschwächt. Die Zeit für den Angriff ist gekommen.", sourceObjective = "Tötet 25 Feuerschwarmschieferschwingen, die über dem Auge von Ysera fliegen, indem Ihr sie mit Eurem Reitdrachen angreift.", completion = "Es ist vollbracht.", sourceObjectiveStatus = "unverified-source-field" }
quests[76337] = { id = 76337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In der Asche glimmt es noch", description = "Ich... kann es kaum glauben, dass das funktioniert hat. Ich werde für immer dankbar sein für das Vertrauen und die Treue eines jeden Einzelnen. Wir hätten diesen Kampf nicht ohne die Hilfe unserer Verbündeten und des Schwarms gewinnen können.\n\nAber der Kampf ist noch lange nicht vorbei. Aus den von uns gesammelten Informationen geht hervor, dass Fyrakk und seine Diener einen weitaus größeren Angriff vorbereiten. Ihre Stützpunkte bestehen weiter und sie liegen beängstigend nah an der Hoffnung des Traums, der Bastion von Amirdrassil.\n\nDas Auge war vielleicht nur ein Ablenkungsmanöver. Wir werden uns bei Amirdrassil mit dem Rest unserer Verbündeten neu gruppieren.", sourceObjective = "Findet Euch bei Merithra bei Amirdrassil ein.", completion = "Danke, dass Ihr gekommen seid, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[76338] = { id = 76338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein besserer Kohlschläger" }
quests[76339] = { id = 76339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Luftspaß von Loch Modan", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[76340] = { id = 76340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Luftspaß von Loch Modan - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[76341] = { id = 76341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Luftspaß von Loch Modan - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[76342] = { id = 76342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht ihnen Feuer!", description = "Nachdem Vyranoth gegangen war, erteilte Fyrakk allen vier Klauen von Vyranoth verschiedene Aufgaben.\n\nMir übergab er die Verantwortung für dieses Lager und befahl mir, die Portale um jeden Preis offen zu halten. Die Druiden der Flamme verstärken die Portale, damit die Verstärkung der Primalisten hindurchkommen kann.\n\nWir sollen diese Portale schließen und ihre Reihen ausdünnen.", sourceObjective = "Schwächt das Primalistenlager in der Primalistenfestung.", completion = "Ihre Truppen zu stören sollte den Traum vorerst schützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[76343] = { id = 76343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die besten Pläne", description = "Fyrakk mag unbesonnen sein, aber er ist kein Dummkopf. Wenn wir den Traum bewahren wollen, so müssen wir seine Pläne so schnell wie möglich untergraben.\n\nIm Kern sind die Primalisten unorganisiert. Infiltriert ihr Lager und sucht nach jeder Art von Hinweis oder Information.\n\nJe mehr Anhaltspunkte wir haben, umso eher wird es uns gelingen, Fyrakk ein für alle Mal das Handwerk zu legen.", sourceObjective = "Findet 4 Hinweise in der Primalistenfestung.", completion = "Diese Notizen sind von Lethka?", sourceObjectiveStatus = "unverified-source-field" }
quests[76344] = { id = 76344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Primalistendirektive", description = "Terro gehörte auch zu Vyranoths Klauen. Er wollte den Traum niemals angreifen und einige der Primalisten, die ihm dienten, könnten auch so denken. Versucht sie davon zu überzeugen, sich unserer Seite anzuschließen.\n\nIch kann Euch das Mal von Vyranoth verleihen, damit Terros Truppen Euch nicht angreifen... Jedenfalls nicht sofort.", sourceObjective = "Überzeugt 5 von Terros Primalisten, sich auf Vyranoths Seite zu schlagen.", completion = "Terro hat sich immer schützend vor die gestellt, die er befehligte. Er hätte gewollt, dass wir alle retten, die wir retten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[76345] = { id = 76345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach Terro", description = "Ich hatte ja keine Ahnung, dass meine alte Wache gewillt ist, an meine Seite zurückzukehren. Ich bin... Ich bin froh, sie zu sehen. Als ich mich dazu entschied, zu Alexstrasza zu gehen, erzählte ich niemandem davon. Ich bin einfach gegangen.\n\nAber wir müssen mehr über Fyrakks Plan in Erfahrung bringen, bevor wir uns persönlichen Dingen zuwenden können. Lasst uns sehen, was Buri uns erzählen kann.", sourceObjective = "Findet weitere Informationen über Fyrakks Plan im Smaragdgrünen Traum.", progress = "Wenn wir nur die anderen Klauen finden könnten...", completion = "Vyranoth wird nicht ruhen, bis Terro nicht gerächt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[76347] = { id = 76347, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht, Ausbruch und Lügen", description = "Buri hat mir erzählt, dass Lethka vorhat, den Glutgipfel zu entzünden, und Vyranoth hat ihre Verfolgung aufgenommen.\n\nLethka hat sich offenbart, da sie wusste, dass Vyranoth ihr folgen würde. Die Macht im Glutgipfel kann diese Barriere zerstören, oder Vyranoth.\n\nWir müssen ihnen hinterher.", sourceObjective = "Bezwingt Lethka am Glutgipfel.", completion = "Der Verlust eines Freundes ist kein Grund, zu feiern. Aber es musste sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[76348] = { id = 76348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besonders bezaubernde Barriere", description = "Buri? Vyranoth?\n\nNachdem sie uns Fyrakk ausgeliefert hatte, hatten wir keine andere Wahl, als ihm zu folgen. Ich weiß nicht, welchen Plan er verfolgt, aber er hat mir und diesen Primalisten befohlen, diese Barriere einzureißen.\n\nWir sind nur wenig vorangekommen, aber Vyranoth wird wollen, dass wir ihm weitere Verzögerungen einbringen.\n\nEinige Fragmente der Barriere sind herausgebrochen worden. Wenn Ihr sie einsammelt, können wir ihre Energie zurück in den Schild kanalisieren.\n\nKann ich es Euch anvertrauen, den Schaden, den ich angerichtet habe, wieder rückgängig zu machen?", sourceObjective = "Sammelt 6 Barrierenfragmente im Smaragdgrünen Traum.", completion = "Danke, dass Ihr seinen Ansturm verhindert habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[76350] = { id = 76350, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zeitenschmied", description = "Seid Ihr hier, um uns zu helfen? Wie Ihr seht, hat sich die Zeitanomalie um die Grenze des Äons aufgelöst, und es gibt viel zu tun.\n\nWir haben einen unserer besten Zeitenschmiede zu Hilfe gerufen, einen Bronzedrachen namens Ferrodormu. Das Problem, abgesehen von all diesem Chaos, ist, dass er spurlos verschwunden ist. Er wollte seine Werkstatt einrichten und sollte schon wieder zurück sein.\n\n<Tempo seufzt entnervt.>\n\nKönnt Ihr ihn suchen gehen?", sourceObjective = "Findet Ferrodormu bei der Schmiede an der Grenze des Äons.", completion = "Wie Ihr seht, stecke ich grad ein bisschen in der Klemme. Meine Schmiede ist nicht nur mit einem Zeitschloss versiegelt, sondern zu allem Übel auch noch bis zum Rand voll mit Feuerelementaren!\n\nUnd als wäre das noch nicht schlimm genug, braucht Klein-Finduin hier DRINGEND einen talentierten Zeitenschmied, der seine Klinge Muschelschalemayne repariert. Ich kann natürlich nicht viel ausrichten, wenn meine vermaledeite Schmiede...\n\n<Ironus gestikuliert vor Frust wild mit seinen Pranken.>\n\nIch wär Euch jedenfalls mächtig dankbar, wenn Ihr mir aushelfen könntet.", sourceObjectiveStatus = "unverified-source-field" }
quests[76351] = { id = 76351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Titanische Bestien", description = "<Dieses kleine Gerät ist aus dem Maul einer Bestie gerollt, die Ihr besiegt habt.\n\nEs sieht wie eine titanische Informationsvorrichtung aus, aber es ist kompakter als die Geräte, die Ihr aus Azeroth kennt.\n\nSoridormi ist sicher sehr daran interessiert.>", sourceObjective = "Kehrt zu Soridormi im Tyrholdreservoir zurück, nachdem Ihr den Zeitriss abgeschlossen habt.", completion = "<Soridormi dreht das Gerät in Ihren Händen.>\n\nDas kam aus dem Maul einer großen Bestie, sagtet Ihr?\n\nIch hoffe, sein Vorbesitzer fand ein schnelles Ende.\n\nIch lege es auf einen der Tische hinter mir, falls Ihr es Euch später ansehen wollt. Vielleicht ist es dann etwas sauberer.", sourceObjectiveStatus = "unverified-source-field" }
quests[76352] = { id = 76352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Packt den Chronohammer aus!", description = "Wenn ich Klein-Finduins Klinge hier reparieren soll, müssen wir erstmal das Zeitschloss an meiner Schmiede knacken. Und wenn man mit einem Hammer ein Schloss zertrümmern kann, dann sollte man mit einem Chronohammer ein Zeitschloss zertrümmern können.\n\nUnglücklicherweise ist mein Hammer grad etwas außer Takt. Aber Glück im Unglück: Wir stecken genau im richtigen Dilemma, um zumindest dieses Problemchen zu lösen. Gleich außerhalb des Temporalen Konfluxes nagen Risse an unserer Zeitlinie und es strömen reihenweise zeitverlorene Hackbratzen hindurch.\n\nVerlasst die Grenze des Äons, säubert die Gegend und ladet meinen Hammer wieder auf.", sourceObjective = "Tötet zeitversetzte Kreaturen und zerstört Risse im Zeitenfluss, um Ironus' Chronohammer wieder zu synchronisieren.", completion = "Ihr habt WAS aus diesen Zeitrissen kommen sehen? Tja, das ist nicht gut!\n\nIch werde Tempo Bescheid sagen. Ich will mir gar nicht vorstellen, was passieren würde, wenn mehr dieser Kreaturen in unserer Zeitlinie herumrandalieren!\n\nAber wie's aussieht, habt Ihr kurzen Prozess mit ihnen gemacht. Ich spüre schon von hier, wie die Temporalenergie aus meinem Hammer strömt!", sourceObjectiveStatus = "unverified-source-field" }
quests[76354] = { id = 76354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für den Hort!", description = "Ich habe eine Lagerkammer im Zeitenfluss, die randvoll ist mit chronomatischen Kisten. Dort bewahre ich zeitverlorene Artefakte aus verschiedenen Zeitlinien auf.\n\nLeider sind die Sicherheitsprotokolle meiner Kammer durch diese vermaledeiten Zeitrisse durcheinandergekommen. Ich bin kurz vorbeigeflogen und musste mit ansehen, wie diese höllischen Plünderer meine Kisten überall verstreut haben!\n\nDa Ihr ohnehin in diese Richtung wollt, könnt Ihr nicht meine Habseligkeiten mitnehmen? Nicht alles natürlich! Nur die wichtigen Sachen.", sourceObjective = "Findet und sammelt Ironus' Artefakte.", progress = "Bei der Hitze meiner Schmiede... Ich schwöre, wenn einer dieser widerlichen Plünderer meine Kisten aufbricht und etwas mitnimmt, werde ich...\n\nNun, wir Bronzedrachen verfügen ja über alle möglichen Techniken, nicht wahr?", completion = "Oh, den Zeitwegen sei Dank. Ihr habt meine Sachen gefunden!\n\n<Ironus untersucht hastig seine Habseligkeiten.>\n\nFür manche mögen diese Relikte völlig unsinnig erscheinen, aber für mich sind das alles Schätze.\n\nOh und macht Euch keine Gedanken über die anderen Kisten. Sobald die Zeitrisse geschlossen sind, mache ich mich auf den Weg und bringe sie zurück in die Kammer.", sourceObjectiveStatus = "unverified-source-field" }
quests[76355] = { id = 76355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn ein Hammer ein Schloss zertrümmern kann...", description = "Jetzt, da der Hammer vollständig aufgeladen ist, brauchen wir einen ordentlichen Hieb gegen das Zeitschloss und KRABUMMS! Um eine zeitgeschaffene Anomalie zu zerstören, geht doch nichts über einen zeitaufgeladenen Hammer!\n\nWir müssten nur die mögliche Implosion der Zeit berücksichtigen und...\n\n<Ironus zögert einen Moment und murmelt einige Berechnungen vor sich hin, bevor er Euch mit einem wenig zuversichtlichen Lächeln ansieht.>\n\nWisst Ihr was? Ihr habt es Euch verdient, ich überlasse Euch die Ehre!", sourceObjective = "Zerstört das Zeitschloss mit dem chronogeschmiedeten Hammer.", completion = "Nun, das lief doch ganz nach Plan, nicht wahr? Es ist ohne Mucks zersplittert, ohne die geringste Erschütterung der Zeit. Ich hatte keinen Zweifel daran.\n\nLeider waren diese Elementare offenbar etwas rastlos und haben die erste Gelegenheit genutzt, um sich davonzumachen!\n\nEin Problem ausgelöscht, und ein Dutzend Probleme entfacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[76356] = { id = 76356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwertstehlende Senger", description = "Diese schmutzigen Schmiedebruten haben Finduin umgehauen und Muschelschalemayne mitgenommen! Sie haben vermutlich die Temporalenergie im Schwert gespürt.\n\nIch habe keinen Schimmer, was sie damit vorhaben, aber es bleibt keine Zeit, es herauszufinden.\n\nAlles, was Ihr getan habt, bringt freilich nicht viel, wenn ich Finduins Klinge nicht mehr habe, um sie zu reparieren. Könntet Ihr sie wohl zurückholen? Schließlich hängt das Schicksal von ganz Azmerloth davon ab!", sourceObjective = "Holt Finduin Wrynngrlgurls Klinge Muschelschalemayne zurück.", progress = "Diese kleinen Elementärchen wurden von Muschelschalemayne wie Zeitmotten von der Chronoflamme angelockt.\n\nIch kann nur hoffen, dass der Schaden nicht zu groß ist.", completion = "Oh, den Zeitwegen sei Dank, Ihr habt Muschelschalemayne geborgen, bevor diese feurigen Fieslinge bleibende Schäden anrichten konnten! Die Klinge ist ein bisschen angesengt, aber nichts, was ich nicht heraushämmern könnte.\n\nAuch gut, dass Ihr unversehrt seid. Ein paar Brandmale, wie ich sehe, aber damit kommt Ihr schon klar.\n\nTragt den Ruß wie das Ehrenmal, das er darstellt.", sourceObjectiveStatus = "unverified-source-field" }
quests[76357] = { id = 76357, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sengslalom", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[76358] = { id = 76358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sengslalom - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[76359] = { id = 76359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sengslalom - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[76361] = { id = 76361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Modewoche", description = "Ah, der große Stylecheck naht, {class}.\n\nDie Kleidung, die Kreativität und die Eleganz des Checks lassen sich wirklich sehen.\n\nSprecht in Sturmwind mit Primo, dem Gesandten des großen Stylechecks, um mehr über das Ereignis zu erfahren.\n\nEin Wort der Warnung, Primo kann mitunter... schwierig sein.", sourceObjective = "Sprecht mit einem Gesandten des großen Stylechecks.", completion = "Denkt Ihr wirklich, dass Ihr bereit seid für den großen Stylecheck?\n\nIn der Aufmachung?", sourceObjectiveStatus = "unverified-source-field" }
quests[76362] = { id = 76362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Schädel mit Geweih", description = "<Trotz der Umgebung scheint dieser Schädel nicht teufelsverderbt zu sein.\n\nAls Ihr Eure Hand danach ausstreckt, fühlt Ihr eine Aura der Ruhe davon ausgehen.\n\nSoridormi ist sicher sehr daran interessiert.>", sourceObjective = "Bringt den Schädel mit Geweih zu Soridormi im Tyrholdreservoir.\n\nBereitgestellter Gegenstand:", completion = "<Soridormi hebt den Schädel mit spitzen Finger auf Augenhöhe.>\n\nIhr sagtet, Ihr hättet ihn bei einem teufelsverderbten Illidan gefunden?\n\nIch vermute, das ist Malfurion.\n\nUnd wir dachten, ihre familiären Probleme in unserer Zeitlinie wären schlimm.", sourceObjectiveStatus = "unverified-source-field" }
quests[76364] = { id = 76364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenschrecken", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
